export default [{"id":42,"question":"سائل يقول: أنا شاب مصاب بمرض أجاركم الله وهو خروج الغازات باستمرار أثناء الصلاة، وقد حُرمت بسبب هذا المرض من أداء السنن الرواتب، كما أن الفروض التي أؤديها يراودني شك في طهارتي فيها، أرجو إفادتي ماذا أعمل فيها، جزاكم الله خيرًا!","title":"ما كيفية صلاة المُبتلي بخروج الغازات أثناء الصلاة؟","answer":"الجواب: لا عليك يا أخي، صلِّ النوافل والفرائض جميعًا، صلِّ هذه وهذه، صلِّ الفرائض والنوافل الرواتب وغيرها، أنت معذور، الذي عنده غازات أو سلس بول دائم، أو امرأة معها استحاضة دائمة، فكُلٌّ يصلي على حسب حاله؛ لكن لا يتوضأ إلا إذا دخل الوقت، إذا دخل وقت الظهر يتوضأ ويصلي الظهر ورواتبها، والنوافل التي يريد، ويقرأ القرآن، ويستمر إلى دخول وقت العصر، فإذا جاء وقت العصر وخرج منه شيء يتوضأ وضوءًا ثانيًا للعصر، ولا يزال يصلي العصر ويصلي قبلها ما تيسر، ويستمر بذكر الله إلى غروب الشمس وهو على طهارته، إذا غربت الشمس توضأ للمغرب وصلى بها صلاة المغرب وصلى النوافل، وهكذا العشاء، سواءً كان غازات أو بولًا أو غير ذلك مما يخرج من الإنسان، لا يضره، الحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nوالنبي ﷺ قال للمستحاضة لما كان معها الدم دائمًا قال: توضئي لكل صلاة فإذا دخل الوقت فتوضأ وصل النوافل والفرائض جميعًا، والحمد لله.","link":"https://binbaz.org.sa/fatwas/2822/ما-كيفية-صلاة-المبتلي-بخروج-الغازات-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0015.mp3","categories":["صلاة المريض"]},{"id":96,"question":"هذا سؤالٌ من مريضٍ، كأنَّه يُريد أن يعرف نفسه فيقول: أحضر للمُستشفى ثلاثة أيام في الأسبوع؛ لأني مصاب بفشل كلوي، وأحضر لجلسات على جهازٍ لتفتيت الدم، ولكن صلاة العصر تفوتني، فأنا لا أنتهي من العلاج إلا بعد صلاة العصر بساعة ونصف، وكرسي الجلوس يكون في وضعٍ مخالفٍ للقبلة. هل أُصلي على أي اتجاهٍ أم أُصليها بعد انتهاء الوقت؟ أفيدوني أثابكم الله.","title":"حكم صلاة مريض الفشل الكلوي وقت الجلسة","answer":"الجواب: يقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، فإذا كنتَ مريضًا يشقُّ عليك كل صلاةٍ في وقتها اجمعها قبل الدُّخول في العملية إذا كان يضرُّك ذلك، فتجمع العصر مع الظهر جمع تقديم. وإن كنت قبل ذلك سليمًا ولكن من أجل العملية فقط؛ فلا مانع من تأخير الصلاة، وصلاتها بعد إجراء العملية، فإذا كنتَ لا تستطيع فعلها وقت العملية فإنَّك تُؤَخِّرها ولا حرج في ذلك. أمَّا بعد إجراء العملية فعليك أن تُصليها على حسب حالك: قائمًا، أو قاعدًا، أو على جنبٍ، أو مُستلقِيًا، على حسب طاقتك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ، وقال النبيُّ ﷺ لعمران بن حُصين وكان مريضًا: صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنبٍ، فإن لم تستطع فمُسْتَلْقِيًا.\nولكن أنت عند دخول العملية في حكم المريض، فلا مانع من تقديم صلاة العصر مع الظهر إذا كان دخولُ العملية بعد الظهر، وإن كان قبل الظهر تُؤخر الظهر مع العصر، وإذا انتهيتَ تُصليهما بعد انتهاء العملية، وبعد قُدرتك على ذلك، ولو في وقت العصر، ولو اصفرَّت الشمسُ: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، إلا إذا قدرت في الوقت أن تُصليها قبل أن تصفرَّ الشمسُ فصلِّها ولو بالإيماء، ولو أنك على جَنْبٍ، أو مُستلقيًا، تُكَبِّر وتقرأ، وتُكبِّر وتنوي الركوع، وتنوي الرفع وتقول: سمع الله لمن حمده، وتنوي السجود وتقول: الله أكبر، وتقول: سبحان ربي الأعلى، وتنوي الرفع وتُكبر وتقول: ربي اغفر لي، ربي اغفر لي، وتُكبر وتهوي إلى السجدة الثانية وتقول: الله أكبر، وتُسبح: سبحان ربي الأعلى، وهكذا تُكمل إذا استطعت ذلك، أما إذا كان شعورك ما هو معك ولا تستطيع؛ فأخِّرْها حتى تنتهي العملية ويرجع لك الشُّعور.\nثم أيضًا مُلاحظة الوضوء: فكل مريضٍ عليه أن يتَّقي الله ويُلاحظ الوضوء: إن استطاع فيتوضأ، أو يُوضِّئه غيرُه: فيغسل وجهه وذراعيه، ويمسح رأسه وأذنيه، ويغسل رجليه إن استطاع، فإن لم يتيسر ذلك تيمم، ويُوضَع عنده ترابٌ تحت الكرسي.\nوقد كتبنا لوزير الصحة سابقًا وعمم على المُستشفيات أنه لا بدَّ أن يكون عندهم ترابٌ ناعمٌ قليلٌ في كيسٍ أو في صحنٍ تحت الكرسي يمسح منه المريض، فيضرب بيديه أو يُقرب إليه ويضرب بيديه ويمسح وجهه وكفَّيه، وهكذا المُستشفى العسكري هنا وغيره يجب أن يُلاحظوا هذا، حتى يكون عند المريض ما يسدّ حاجته إذا كان لا يستطيع الماء، فيكون عند كرسيه إناءٌ فيه تراب جيد، حسن، أو كيسٌ يُفتح له وقت الصلاة، فيضرب بيديه ثم يمسح وجهه وكفَّيه، أو القيّم عليه يقول له وهو يضرب التراب، ويمسح وجهه وكفيه، وينوي المريضُ، وهذا ينوب عنه لمسح وجهه وكفيه، مع نية المريض، ويقوم هذا مقام الطَّهارة بالماء.\nوأما بالنسبة للاستنجاء من البول والغائط: فهذا يكون بالمناديل، فيمسح نفسه بالمناديل الطاهرة ثلاث مرات أو أكثر، ويكفي عن الماء، فيمسح إن استطاع أو يمسحه الممرض إذا كان لا يستطيع، ويكفي عن الماء.","link":"https://binbaz.org.sa/fatwas/3124/حكم-صلاة-مريض-الفشل-الكلوي-وقت-الجلسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0075.mp3","categories":["صلاة المريض"]},{"id":225,"question":"أحد زملائي أُصيب في حادث سيارةٍ، وأُصيب إصابةً بالغةً، حيث مكث خمسةً وخمسين يومًا مُغْمى عليه، وبعدها أفاق من ذلك، وطلب من الأطباء إحضار ترابٍ ليتيمَّم به ليُصلي، فلم يفعلوا، وترك الصلاة ثلاثة أشهر غير الخمسين التي حصل فيها الإغماء.سؤالي: ما حكم عمله هذا؟ وهل يُعيد الصلاة في الإغماء وما بعده أم ماذا يفعل؟","title":"ما حكم ما يفوت من صلوات حال الإغماء؟","answer":"الجواب: هذا غلطٌ، الواجب عليه أن يُصلي على حسب حاله؛ لأنَّ الله قال: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وقد أجمع العلماء على أنَّ المؤمن يُصلي على حسب حاله، فإذا لم يجد ماءً ولا ترابًا، ولم يستطع التيمم ولا الوضوء؛ صلَّى على حسب حاله.\nوقد صلَّى الصحابةُ في عهد النبيِّ ﷺ لما بعثهم يلتمسون عِقد عائشة بغير وضوءٍ ولا تيممٍ، ما كان عندهم ماء، والتيمم لم يُشرع بعد، فصلّوا على حسب حالهم، ولم يُنكر عليهم النبيُّ ﷺ.\nفالواجب على المريض وعلى غيره من الناس أن يُصلي على حسب حاله، إن وجد ماءً صلَّى بالماء، وإن لم يجد ماءً تيمم، وإن مُنع من التيمم ولم يتيسر ما يتمم به صلَّى على حسب حاله، كالأسير الذي يُؤسر في الخشبة ونحوها، ما يتمكن من ماء ولا تراب؛ يُصلي على حسب حاله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ.\nوعليه القضاء؛ لأنه تركها بعذرٍ، ترك الصلاة يظن أنه معذورٌ، ما تركها عمدًا ومخالفةً لشرع الله، لو تركها هكذا كان كافرًا، لكنه تركها يظن أنه معذورٌ وأنه يجوز له الترك، فعليه القضاء، عليه أن يتوضأ ويقضي هذه الأيام التي تركها.\nأما أيام الإغماء فاختلف فيها العلماء، فإن قضاها فهو أحوط، وإن لم يقضها فلا بأس؛ لأنها مدة طويلة، والإغماء يُشبه الجنون، فلا قضاء عليه إن شاء الله، وإن قضى فلا حرج، لكن لو كان الإغماءُ قليلًا: يومين أو ثلاثًا؛ يقضي، فقد أُغمي على بعض الصحابة وقضى المدة اليسيرة، لكن إذا زاد على الثلاث وصار كثيرًا فالأصح فيه عدم القضاء؛ لأنه حينئذٍ أشبه بالمجنون والمعتوه، أما الإغماء ليومين أو ثلاث فهذا أشبه بالنَّائم فيقضي.","link":"https://binbaz.org.sa/fatwas/4069/ما-حكم-ما-يفوت-من-صلوات-حال-الاغماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0232.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":305,"question":"لي أختٌ تبلغ من العمر الثلاثين، ولم تُصلِّ؛ لأنها مشلولة الأعضاء، ولم تُحرك جزءًا من جسمها، ولكن عقلها سليمٌ، فهل تسقط عنها الصلاةُ؟ حتى الوضوء لا تستطيع، ولا القيام لحاجتها، لم تقدر، وأغلب الوقت لم تكن على طهارةٍ، هل تجب عليها الصَّلاة؟","title":"ما كيفية صلاة المقعَد الذي لا يمكنه الحركة؟","answer":"الجواب: ما دام عقلُها معها عليها أن تُصلي بالنية والكلام، وعلى مَن لديها من أمِّها أو أبيها أو أختها أو نحو ذلك أن يُيممنَّها، ليغسلن وجهها إن أمكن، يغسل وجهها ويداها إن كان لها يدان، وكذلك يمسح رأسها وأذناها، وتغسل رجلاها، على مَن عندها من أمٍّ أو خادمةٍ أن تعمل معها ذلك.\nوتُعلَّم الصلاة، تُعلَّم أن تُصلي بالنية والكلام، وإذا استطاعت الركوع تركع في الهواء، وإن استطاعت السجود تسجد ولو كانت قاعدةً، فإن كانت ما تستطيع الجلوس تُصلي على جنبها أو مُستلقيةً على حسب حالها: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، المقصود أنها تُعلّم.\nالنبي ﷺ لما سأله عمران بن حصين -وكان به مرضٌ- قال له النبيُّ ﷺ: صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنبٍ، فإن لم تستطع فمُستلقيًا يتعلَّم حسب طاقته.\nوهكذا في الوضوء، وهكذا في إزالة الأذى منها –النجاسة- أمها أو أختها أو خادمة لها تُزيل النَّجاسة بالمناديل ونحوها، تمسح فرجها بالمنديل، ويكون عندها مناديل نظيفة طاهرة يمسح بها الفرج ثلاث مرات، أو خمس مرات، أو سبع مرات، حتى ينقى المحل، الأفضل أن يكون على وترٍ، وثلاث هذا أقلّ شيءٍ، لا يُنقص عن ثلاثٍ حتى ينقى المحل، فإن كان ما أُنقي بالثلاث فأربع، وإذا أُنقي بأربعٍ يكمل خامسة أفضل؛ لقول النبي ﷺ: ومَن استجمر فليُوتر، وإذا كمل بستٍّ، كمل بسابعةٍ هكذا.\nالمقصود أنَّ هذا الاستجمار يُجزئ في إزالة الأذى من الدُّبر والقُبُل في حقِّ المشلولة هذه، والمريض، وأشباهه ممن لا يستطيع، وهكذا الصَّحيح، حتى الصحيح لو استجمر كفاه عن الماء: إذا استجمر ثلاثًا فأكثر وأنقى المحلَّ باللبِن أو بالمناديل أو بغير ذلك من الطاهرات، إلا العظم والروث، فلا يُستنجى بهما، العظام والأرواث لا يُستنجى بهما، لكن إذا استجمر بلبِنٍ أو بحجرٍ أو بأخشابٍ تُناسب أو بمناديل تُناسب حتى أزال الأذى، وحتى أنقى المحلَّ، بثلاثٍ أو بأكثر من ذلك، لكن لا ينقص عن ثلاثٍ، لا بدّ من ثلاثٍ أو أكثر، ولا بدّ من إنقاء المحلّ، ولو زاد على الثلاث لا بدّ من إنقاء المحل حتى يتنظَّف، ويُجزئ عن الماء، فإذا حصل الماء مع ذلك كان أكمل وأفضل.\nوتُصلي على حسب حالها: إن استطاعت الركوع ركعت، السجود سجدت، ما تستطيع تركع في الهواء قليلًا، وتسجد قليلًا في الهواء أخفض من الركوع، حسب طاقتها، ما تستطيع أن تتحرك بالكلية فبالنية: تُكبر تقول: \"الله أكبر\"، وتقرأ الفاتحة، وتقرأ ما تيسر معها، ثم تُكبر وتنوي الركوع وتقول: \"سبحان ربي العظيم، سبحان ربي العظيم\"، ثم تقول: \"سمع الله لمَن حمده\" ناويةً الرفع من الركوع، تقول: \"ربنا ولك الحمد\"، إلى آخره، ثم تقول: \"الله أكبر\" ناويةً السجود، تقول: \"سبحان ربي الأعلى، سبحان ربي الأعلى\"، إلى آخره، ثم تقول: \"الله أكبر\" ناويةً الجلسة بين السجدتين، تقول: \"ربي اغفر لي، ربي اغفر لي\"، ثم تقول: \"الله أكبر\" ناويةً السجدة الثانية، وتقول: \"سبحان ربي الأعلى، سبحان ربي الأعلى\"، ثم تقول: \"الله أكبر\" ناويةً القيام، ثم تقرأ، وهكذا حتى تُكمل.","link":"https://binbaz.org.sa/fatwas/4308/ما-كيفية-صلاة-المقعد-الذي-لا-يمكنه-الحركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0355.mp3","categories":["صلاة المريض"]},{"id":924,"question":"مَن على لباسه بقع دمٍ هل يُصلي بها أو ينتظر حتى يحضر له لباسٌ نظيفٌ؟","title":"حكم صلاة مريض بثوبه دم ولا يوجد غيره","answer":"الجواب: يُصلي على حسب حاله، لا يدع الصلاة حتى يخرج الوقت، بل يُصلي على حسب حاله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، والواجب على المسؤولين أن يغسلوا ما به من الدم، أو يبدلوا ثوبه بثوبٍ آخر، فإذا ضاق الوقتُ عليه ولم يبدلوا ثوبَه ولم يغسلوه صلَّى على حسب حاله، وأما إذا كان إبدال الثوب متيسرًا أو غسله متيسرًا فإنه يبدل أو يغسل قبل خروج الوقت، فإن تأخَّروا عنه فلا يجوز ترك الصلاة حتى يخرج الوقت، بل يُصلي في الوقت ولو كان في ثوبه شيءٌ من النَّجاسة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ.","link":"https://binbaz.org.sa/fatwas/20960/حكم-صلاة-مريض-بثوبه-دم-ولا-يوجد-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0756المريض إذا كان على لباسه بقع دم هل يصلي بها أو ينتظر حتى يحضر له لباس نظيف؟ ابن باز.mp3","categories":["صلاة المريض"]},{"id":927,"question":"من المعلوم أنَّ المريض بعد إجراء العملية الجراحية يبقى مُخدَّرًا حتى يفيق، وبعد ذلك يبقى متألِّمًا من العملية لساعات، فهل يُصلي قبل دخول العملية، والوقت في الصلاة لم يَحِن بعد، أم يُؤخّر الصلاة حتى يكون قادرًا على أدائها بالحضور الحسي، ولو تأخَّر ذلك أكثر من يومٍ؟","title":"حكم ما يفوت من صلوات لإجراء جراحة","answer":"الجواب: الواجب أولًا على الطبيب أن ينظر في الأمر: فإذا أمكن أن يتأخَّر بدء العلاج حتى يدخل الوقتُ ويُصلي الظهر والعصر جميعًا إذا دخل وقتُ الظهر، أو المغرب في الليل، إذا دخل المغربُ صلَّى المغرب والعشاء جميعًا، أما إذا كان العلاجُ..... فإنَّ المريض معذورٌ، فإذا أفاق صلَّى، قضى ما عليه ولو بعد..... متى أفاق قضى ما عليه، والحمد لله، ولا شيء عليه، مثل: النائم إذا أفاق وانتبه ورجع إليه وعيُه صلَّى الأوقات التي فاتته على الترتيب، يُرتِّبها: الظهر، العصر، المغرب، العشاء، على الترتيب، والحمد لله، ولا حرجَ عليه.","link":"https://binbaz.org.sa/fatwas/20957/حكم-ما-يفوت-من-صلوات-لاجراء-جراحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0753هل يجوزأن يصلي قبل دخول العملية والوقت للصلاة لم يحن بعد أو يؤخر الصلاة بعد العملية؟ ابن باز.mp3","categories":["وقت الصلاة","صلاة المريض"]},{"id":1279,"question":"أنا أحضر للمُستشفى ثلاثة أيام في الأسبوع؛ لأني مُصابٌ بفشل كلوي، وأحضر لجلسات على جهاز لتفتيت الدم، ولكن صلاة العصر تفوتني، فأنا لا أنتهي من العلاج إلا بعد صلاة العصر بساعةٍ ونصف، وكرسي الجلوس يكون في وضعٍ مخالفٍ للقبلة. هل أُصلي على أي اتجاهٍ؟ أم هل أُصليها بعد انتهاء الوقت؟ أفيدوني أثابكم الله.","title":"حكم تأخير الصلاة وجمعها لمريض الكُلَى","answer":"الجواب:\nيقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، إذا كنتَ مريضًا يشقّ عليك كلُّ صلاةٍ في وقتها اجمعها قبل الدخول في العملية، إذا كان يضرُّك ذلك فاجمع العصر مع الظهر جمع تقديمٍ، وإن كنتَ أنت قبل ذلك سليمًا ولكن من أجل العملية فقط فلا مانع من تأخير الصلاة، وتُصليها بعد إجراء العملية، إذا كنتَ لا تستطيع فعلها وقت العملية فإنَّك تُؤخِّرها ولا حرج في ذلك.\nأما بعد إجراء العملية فصلِّ على حسب حالك: قائمًا، أو قاعدًا، أو على جنب، أو مُستلقيًا، على حسب طاقتك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ، قال النبيُّ ﷺ لعمران بن حصين لما كان مريضًا: صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنبٍ، فإن لم تستطع فمُستلقيًا، ولكن أنت عند الدخول في العملية في حكم المريض، فلا مانع أن تُقدم صلاة العصر مع الظهر إذا كان دخول العملية بعد الظهر، وإن كان قبل الظهر تُؤخِّر الظهر مع العصر، وإذا انتهيت صليتهما بعد انتهاء العملية، وبعد قدرتك على ذلك، ولو في وقت العصر، ولو اصفرَّت الشمسُ: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ، إلا إذا قدرتَ في الوقت أن تُصليها قبل أن تصفرَّ الشمسُ فصلّها ولو بالإيماء، ولو أنك على جنبٍ، أو مُستلقيًا تُكبِّر وتقرأ، تكبر وتنوي الركوع وتقول: الله أكبر، وتنوي الرفع وتقول: سمع الله لمن حمده، وتنوي السجود وتقول: سبحان ربي الأعلى، وتُكبر وتنوي الرفع وتقول: ربي اغفر لي، ربي اغفر لي، وتُكبر وتنوي السجدة الثانية وتقول: الله أكبر، وتُسبح: سبحان ربي الأعلى، سبحان ربي الأعلى، وهكذا، كمّل هكذا، هكذا إن استطعتَ ذلك، أما إن كان شعورك ما هو معك، ما تستطيع، فأخِّرها حتى تنتهي العملية ويرجع لك الشعور.\nثم أيضًا ملاحظة الوضوء: كل مريض عليه أن يتَّقي الله ويُلاحظ: إن استطاع الوضوء توضأ، أو وضَّأه غيرُه: يغسل وجهه ويديه، ويمسح رأسه، ويغسل رجليه، وأما الخارج -الاستنجاء والبول والغائط- فهذا بالمناديل، يمسح نفسه بالمناديل ثلاث مراتٍ أو أكثر، ويكفي عن الماء، الخارج من الدبر والبول بالمناديل الطاهرة، يمسح إن استطاع، أو يمسحه الممرض إذا كان لا يستطيع، ويكفي عن الماء.  والوضوء إن كان يستطيع يُوضِّئ نفسه، وإلا وضَّأه غيرُه: يغسل وجهه وذراعيه، ويمسح رأسه وأذنيه، ويغسل رجليه إن استطاع، فإن لم يتيسر ذلك تيمم، يُوضع عنده ترابٌ تحت الكرسي.\nلقد كتبنا لوزير الصحة سابقًا، وعمَّم على المستشفيات، يكون عندهم في كيسٍ، أو في صحنٍ تحت الكرسي، ترابٌ ناعمٌ قليل يمسح منه: يضرب بيديه، أو يُقرب إليه ويضرب يديه ويمسح وجهه وكفيه، وهكذا المستشفى العسكري هنا وغيره، يجب أن يُلاحظوا هذا، حتى يكون المريضُ عنده ما يسدّ حاجته، إذا كان لا يستطيع الماء يكون عند كرسيه إناءٌ فيه ترابٌ جيدٌ حسنٌ، أو كيسٌ يُفتح له قبل، يضرب بيديه ثم يمسح وجهه وكفيه، أو القيِّم عليه يقول له يضرب التراب ويمسح وجهه وكفّيه، وهو ينوي، المريض ينوي، وهذا يكون ينوب عنه من مسح وجهه وكفّيه، مع نية المريض، ويقوم هذا مقام الطهارة بالماء، وأما الدُّبُر والقُبُل فهذا مثلما تقدم: يُمسح بالمناديل ثلاث مرات أو أكثر، ويكفي عن الاستنجاء.","link":"https://binbaz.org.sa/fatwas/21326/حكم-تاخير-الصلاة-وجمعها-لمريض-الكلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1069أعمل غسل كلى ثلاث وأكون مدة طويلة على الكرسي في غير أتجاه القبلة فهل أصلي.mp3","categories":["صلاة المريض"]},{"id":3125,"question":"رجل يستطيع أن يأتي، ولكنه يصلي مستلقيًا، لا يستطيع أن يصلي متربعًا، فكيف يقف في الصف؟","title":"حكم مَن لا يستطيع الصلاة إلا مستلقيًا؟","answer":"الجواب: يصلى في بيته.\nس: يستطيع ينام في المسجد، ولكن لا يستطيع الجلوس متربعا؟\nالشيخ: ما يستطيع الجلوس غير متربع؟\nالطالب: يقول: أنام على ظهري لا بد أن أستلقي.\nالشيخ: لا يجي، يصلي في بيته، معذور.","link":"https://binbaz.org.sa/fatwas/23286/حكم-من-لا-يستطيع-الصلاة-الا-مستلقيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة من لا يستطيع القيام في الصف.mp3","categories":["صلاة المريض"]},{"id":3410,"question":"بعض المرضى إذا سوّى عملية في عينيه، ومنعه الطبيب من السجود؛ يلاحظ على بعضهم أنه يصلي جالسًا، وقد يتيمم؟","title":"حكم المريض الذي منعه الطبيب من السجود","answer":"الجواب: يسجد في الهواء، إذا كان منعه من السجود يخفض رأسه أكثر من الركوع، ولا يسجد، ويمسح إنْ كان عليه عِصابة يمسح عليها، يغسل وجهه، ويمسح على العصابة.\nس: لكن صلاته جالسًا؟\nالشيخ: لا ما يجوز، يجب أن يقوم إلا إذا كان مريضًا.","link":"https://binbaz.org.sa/fatwas/23582/حكم-المريض-الذي-منعه-الطبيب-من-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سجود المريض الذي منعه الطبيب من السجود.mp3","categories":["صلاة المريض"]},{"id":3412,"question":"المريض في المستشفى ولا يستطيع القيام ولا القعود.. يستقبل القبلة بأطراف رجليه أم بوجهه؟","title":"كيف يستقبل المريض القبلة عند الصلاة؟","answer":"الجواب: تكون رجلاه إلى القبلة، يوجه رجليه كلها إلى القبلة.\nس: هل يكون رأسه، للغرب، للشرق، ورجلاه...؟\nالشيخ: وجهه إلى القبلة، ورجلاه كلها إلى القبلة، يمتد إلى القبلة، القبلة تختلف... عندنا القبلة غرب، وفي بلاد أخرى شمال، وفي بلاد جنوب، تختلف الجهات، المقصود يكون إلى جهة القبلة، إذا كان مستلقيًا إلى جهة القبلة، أما إذا كان على جنبه يكون وجهه إلى القبلة، يكون على جنبه الأيمن وجهه إلى القبلة، وهكذا إذا كان جنبه الأيسر يكون وجهه إلى القبلة، وإذا كان مستلقيًا تكون رجلاه إلى القبلة.","link":"https://binbaz.org.sa/fatwas/23584/كيف-يستقبل-المريض-القبلة-عند-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يستقبل المريض القبلة عند الصلاة.mp3","categories":["صلاة المريض"]},{"id":3916,"question":"بعض المرضى إذا نصحته يقول: أنا ما أصلي حتى أشفى؟","title":"حكم ترك المريض الصلاة وقت مرضه","answer":"الجواب: يُعَلّم بالرفق والحكمة ويقول له: يجب عليك أن تصلي على حالك، ولو أنك على جَنْب، ولو ما استطاع الماء، ولو بالتيمم، وإذا ما استطاع يتيمم يَمَّمَه مَنْ حوله من أقاربه، أو خَدَمِه؛ حتى يصليها في وقتها ولا يؤخرها.","link":"https://binbaz.org.sa/fatwas/24134/حكم-ترك-المريض-الصلاة-وقت-مرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المريض الذي يقول أنا ما أصلي حتى أشفى.mp3","categories":["صلاة المريض"]},{"id":4478,"question":"الطَّهارة عليه في كل صلاةٍ: المُستحاضة وصاحب السلس؟","title":"هل يتطهر صاحب السلس والمستحاضة لكل وقت؟","answer":"الجواب: نعم، كل وقت، ما هو لكل صلاةٍ، لكل وقتٍ.\nس: كل فريضةٍ يعني؟\nج: فلو اغتسلت في الظهر أو توضَّأت للظهر جاز أن تُصلي في الظهر ما شاءت من الصَّلوات، وتقرأ وتطوف بمكة إلى العصر.","link":"https://binbaz.org.sa/fatwas/24757/هل-يتطهر-صاحب-السلس-والمستحاضة-لكل-وقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب الطَّهارة في كل صلاةٍ على المُستحاضة وصاحب السلس.mp3","categories":["صلاة المريض"]},{"id":5095,"question":"سائل يقول: أنا شاب مصاب بمرض -أجاركم الله- وهو خروج الغازات باستمرار أثناء الصلاة، وقد حُرمت بسبب هذا المرض من أداء السنن الرواتب، كما أن الفروض التي أؤديها يراودني شك في طهارتي فيها، أرجو إفادتي ماذا أعمل فيها، جزاكم الله خيرًا!","title":"ما كيفية صلاة صاحب الحدث الدائم؟","answer":"الجواب: لا عليك يا أخي، صلِّ النوافل والفرائض جميعًا، صلِّ هذه وهذه، صلِّ الفرائض والنوافل الرواتب وغيرها، أنت معذور، الذي عنده غازات أو سلس بول دائم، أو امرأة معها استحاضة دائمة، فكل يصلي على حسب حاله؛ لكن لا يتوضأ إلا إذا دخل الوقت:  إذا دخل وقت الظهر يتوضأ ويصلي الظهر ورواتبها، والنوافل التي يريد، ويقرأ القرآن، ويستمر إلى دخول وقت العصر.  فإذا جاء وقت العصر وخرج منه شيء يتوضأ وضوءًا ثانيًا للعصر، ولا يزال يصلي العصر ويصلي قبلها ما تيسر، ويستمر بذكر الله إلى غروب الشمس وهو على طهارته. إذا غربت الشمس توضأ للمغرب وصل بها صلاة المغرب وصلى النوافل، وهكذا العشاء. سواءً كانت غازات أو بولًا أو غير ذلك مما يخرج من الإنسان، لا يضره، الحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. والنبي ﷺ قال للمستحاضة لما كان معها الدم دائمًا قال: توضئي لكل صلاة. فإذا دخل الوقت يتوضأ ويصلي النوافل والفرائض جميعًا، والحمد لله.","link":"https://binbaz.org.sa/fatwas/29999/ما-كيفية-صلاة-صاحب-الحدث-الداىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 15.mp3","categories":["صلاة المريض"]},{"id":5139,"question":"يقول هذا السائل: أن هذا سؤالٌ من مريضٍ، كأنَّه يُريد أن يعرف نفسه فيقول: أحضر للمُستشفى ثلاثة أيام في الأسبوع؛ لأني مصاب بفشل كلوي، وأحضر لجلسات على جهازٍ لتفتيت الدم، ولكن صلاة العصر تفوتني، فأنا لا أنتهي من العلاج إلا بعد صلاة العصر بساعة ونصف، وكرسي الجلوس يكون في وضعٍ مخالفٍ للقبلة. هل أُصلي على أي اتجاهٍ أم أُصليها بعد انتهاء الوقت؟ أفيدوني أثابكم الله.","title":"ما كيفية الطهارة والصلاة للمريض وذوي الأعذار؟","answer":"الجواب: يقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، فإذا كنتَ مريضًا يشقُّ عليك كل صلاةٍ في وقتها؛ اجمعها قبل الدُّخول في العملية إذا كان يضرُّك ذلك، فتجمع العصر مع الظهر جمع تقديم. وإن كنت قبل ذلك سليمًا ولكن من أجل العملية فقط؛ فلا مانع من تأخير الصلاة، وصلاتها بعد إجراء العملية، فإذا كنتَ لا تستطيع فعلها وقت العملية فإنَّك تُؤَخِّرها ولا حرج في ذلك. أمَّا بعد إجراء العملية فعليك أن تُصليها على حسب حالك: قائمًا، أو قاعدًا، أو على جنبٍ، أو مُستلقِيًا، على حسب طاقتك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ، وقال النبيُّ ﷺ لعمران بن حُصين وكان مريضًا: صلِّ قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنبٍ، فإن لم تستطع فمُسْتَلْقِيًا. ولكن أنت عند دخول العملية في حكم المريض، فلا مانع من تقديم صلاة العصر مع الظهر إذا كان دخولُ العملية بعد الظهر، وإن كان قبل الظهر تُؤخر الظهر مع العصر، وإذا انتهيتَ تُصليهما بعد انتهاء العملية، وبعد قُدرتك على ذلك، ولو في وقت العصر، ولو اصفرَّت الشمسُ: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، إلا إذا قدرت في الوقت أن تُصليها قبل أن تصفرَّ الشمسُ فصلِّها ولو بالإيماء، ولو أنك على جَنْبٍ، أو مُستلقيًا، تُكَبِّر وتقرأ، وتُكبِّر وتنوي الركوع، وتنوي الرفع وتقول: سمع الله لمن حمده، وتنوي السجود وتقول: الله أكبر، وتقول: سبحان ربي الأعلى، وتنوي الرفع وتُكبر وتقول: ربي اغفر لي، ربي اغفر لي، وتُكبر وتهوي إلى السجدة الثانية وتقول: الله أكبر، وتُسبح: سبحان ربي الأعلى، وهكذا تُكمل إذا استطعت ذلك، أما إذا كان شعورك ما هو معك ولا تستطيع فأخِّرْها حتى تنتهي العملية ويرجع لك الشُّعور. ثم أيضًا مُلاحظة الوضوء: فكل مريضٍ عليه أن يتَّقي الله ويُلاحظ الوضوء، إن استطاع الوضوء توضأ، أو يُوضِّئه غيرُه، فيغسل وجهه ويديه، ويمسح رأسه، ويغسل رجليه وأما الخارج الاستنجاء والبول والغائط، فهذا بالمناديل يمسح نفسه بالمناديل ثلاث مرات أو أكثر، ويكفي عن الماء الخارج من الدبر والبول بالمناديل الطاهرة يمسح إن استطاع، أو يمسحه الممرض إذا كان لا يستطيع، ويكفي عن الماء، والوضوء إن كان يستطيعه بنفسه وضأ نفسه وإلا وضأه غيره؛ يغسل وجهه وذراعيه، ويمسح رأسه وأذنيه، يغسل رجليه إن استطاع، فإن لم يتيسر ذلك؛ تيمم، ويُوضَع عنده ترابٌ تحت الكرسي. وقد كتبنا لوزير الصحة سابقًا وعمّم على المُستشفيات أنه لا بدَّ أن يكون عندهم ترابٌ ناعمٌ قليلٌ في كيسٍ أو في صحنٍ تحت الكرسي، تراب ناعم قليل يمسح منه، فيضرب بيديه أو يُقرب إليه ويضرب بيديه ويمسح وجهه وكفَّيه، وهكذا المُستشفى العسكري هنا وغيره يجب أن يُلاحظوا هذا، حتى يكون عند المريض ما يسدّ حاجته إذا كان لا يستطيع الماء، فيكون عند كرسيه إناءٌ فيه تراب جيد، حسن، أو كيسٌ يُفتح له وقت الصلاة، فيضرب بيديه ثم يمسح وجهه وكفَّيه، أو القيّم عليه يقول له وهو يضرب التراب، ويمسح وجهه وكفيه، وينوي المريضُ، وهذا ينوب عنه لمسح وجهه وكفيه، مع نية المريض، ويقوم هذا مقام الطَّهارة بالماء. وأما الدبر والقبل فهذا مثلما تقدم يمسح بالمناديل ثلاث مرات أو أكثر ويكفي عن الاستنجاء.","link":"https://binbaz.org.sa/fatwas/30054/ما-كيفية-الطهارة-والصلاة-للمريض-وذوي-الاعذار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 75.mp3","categories":["صلاة المريض"]},{"id":5610,"question":"الرجل الذي به سلس هل يجب عليه خلع السراويل؟","title":"ما يفعل مَن به سلس فيما يصيب ثوبه أثناء الصلاة؟","answer":"الجواب: الذي فيه سلس يلاحظه للصلاة وقت الفرض، فيُصلي على حسب حاله، يتوضأ بعد دخول الوقت ويُصلي على حسب حاله، يستنجي ويُصلي على حسب حاله ولو خرج شيء، لكن يتوضأ بعد دخول الوقت كالمستحاضة سواء بسواء، وإن كانت سراويله فيها نجاسة يغسلها أو يبدلها، أما إن حصلت النَّجاسة في نفس الوقت وهو يُصلي فلا حرج ما دام في الوقت حتى يخرج الوقت.\nس: على هذا يُقدم ستر العورة على اجتناب النَّجاسة؟\nج: نعم.[1]","link":"https://binbaz.org.sa/fatwas/31577/ما-يفعل-من-به-سلس-فيما-يصيب-ثوبه-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 050.mp3","categories":["صلاة المريض"]},{"id":6602,"question":"إذا كان رجل فيه ريح دائم، فإذا توضأ، ثم ذهب إلى الصلاة حدث منه ماذا عليه أن يعمل...؟","title":"ما يعمل من ابتلي بسلس في الريح؟","answer":"الجواب: هذا فيه تفصيل: إن كانت الريح مستمرة، وهي الفساء، يعني الريح، الفساء يعرفها الناس... والضراط: ما له صوت، يسمى الضراط، وما ليس له صوت: يسمى فساء، ولما قال أبو هريرة -رضي الله عنه وأرضاه-: أن النبي ﷺ قال: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ قالوا: يا أبا هريرة ما هو الحدث؟ قال: «فساء، وضراط» يعني هذا نوع منه، نوع من الحدث، والبول، والغائط، وأكل اللحم الإبل، والنوم، كل هذه أحداث. فالمقصود: إذا كانت الريح معه مستمرة؛ فهو مثل صاحب السلس، يصلي على حسب حاله، لكن لا يتوضأ إلا إذا دخل الوقت، إذا دخل الوقت يتوضأ، ويصلي، ولو خرجت الريح منه، ولو في الصلاة، ولو بال في الصلاة، مادام البول مستمرًّا معه، ما فيه حيلة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هذا يسمى صاحب السلس، هذا مثله لما كانت الريح دائمة.  أما لا، ما هي بدائمة، لكن تعرض له، إن عرضت في الصلاة، فليمسك إن استطاع، فإن شق عليه؛ يحدث، ويخرج، ويتوضأ، ويصلي، ولو في بيته، إذا فاتته الصلاة، الحمد لله، يقول النبي ﷺ: لا صلاة في حضرة الطعام، ولا وهو يدافعه الأخبثان يعني البول، والغائط، وهكذا الريح .. إذا كانت تؤذيه، ولا يستطيع معها الصلاة، يخرجها، ويصلي في بيته، يتوضأ، ويصلي، أما إذا كانت هي مستمرة معه -دائمة معه- يعني لا يستطيع معها الصلاة، يخرجها، ويصلي في بيته، يذهب يتوضأ، ويصلي، أما إذا كانت إنما هي مستمرة معه -دائمة معه- يعني لا يستطيع .. منها، فهذا معذور، فهو يتوضأ إذا دخل الوقت، ويصلي على حسب حاله، ولو خرجت حال ركوعه، أو سجوده، ونحو ذلك. السؤال: يعني يجتنب المسجد؟ الجواب: لا، يصلي مع الناس.","link":"https://binbaz.org.sa/fatwas/2455/ما-يعمل-من-ابتلي-بسلس-في-الريح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_982.mp3","categories":["صلاة المريض"]},{"id":6606,"question":"إذا كان رجل فيه ريح دائم، فإذا توضأ، ثم ذهب إلى الصلاة حدث منه ماذا عليه أن يعمل...؟","title":"ما يعمل من ابتلي بسلس في الريح؟","answer":"الجواب: هذا فيه تفصيل: إن كانت الريح مستمرة، وهي الفساء، يعني الريح، الفساء يعرفها الناس... والضراط: ما له صوت، يسمى الضراط، وما ليس له صوت: يسمى فساء، ولما قال أبو هريرة -رضي الله عنه وأرضاه-: أن النبي ﷺ قال: لا تقبل صلاة أحدكم إذا أحدث حتى يتوضأ قالوا: يا أبا هريرة ما هو الحدث؟ قال: «فساء، وضراط» يعني هذا نوع منه، نوع من الحدث، والبول، والغائط، وأكل اللحم الإبل، والنوم، كل هذه أحداث. فالمقصود: إذا كانت الريح معه مستمرة؛ فهو مثل صاحب السلس، يصلي على حسب حاله، لكن لا يتوضأ إلا إذا دخل الوقت، إذا دخل الوقت يتوضأ، ويصلي، ولو خرجت الريح منه، ولو في الصلاة، ولو بال في الصلاة، مادام البول مستمرًّا معه، ما فيه حيلة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هذا يسمى صاحب السلس، هذا مثله لما كانت الريح دائمة.  أما لا، ما هي بدائمة، لكن تعرض له، إن عرضت في الصلاة، فليمسك إن استطاع، فإن شق عليه؛ يحدث، ويخرج، ويتوضأ، ويصلي، ولو في بيته، إذا فاتته الصلاة، الحمد لله، يقول النبي ﷺ: لا صلاة في حضرة الطعام، ولا وهو يدافعه الأخبثان يعني البول، والغائط، وهكذا الريح .. إذا كانت تؤذيه، ولا يستطيع معها الصلاة، يخرجها، ويصلي في بيته، يتوضأ، ويصلي، أما إذا كانت هي مستمرة معه -دائمة معه- يعني لا يستطيع معها الصلاة، يخرجها، ويصلي في بيته، يذهب يتوضأ، ويصلي، أما إذا كانت إنما هي مستمرة معه -دائمة معه- يعني لا يستطيع .. منها، فهذا معذور، فهو يتوضأ إذا دخل الوقت، ويصلي على حسب حاله، ولو خرجت حال ركوعه، أو سجوده، ونحو ذلك. السؤال: يعني يجتنب المسجد؟ الجواب: لا، يصلي مع الناس.","link":"https://binbaz.org.sa/fatwas/2455/ما-يعمل-من-ابتلي-بسلس-في-الريح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_982.mp3","categories":["صلاة المريض"]},{"id":7435,"question":"ما دليلكم في جمع المريض صلاة الظهر مع العصر، والمغرب مع العشاء؟","title":"أدلة جمع المريض للصلاة","answer":"الجواب: جاء في عدة أحاديث منها حديث ابن عباس، جمع ﷺ في المدينة من غير خوف ولا مطر، وفي رواية من غير خوف ولا سفر، هذا دل على أن السفر والمطر والخوف يجمع لأجله، فالمرض من باب أولى. كذلك حديث حمنة بنت جحش ثبت في السنة أن النبي ﷺ أذن لها بالجمع، وكانت مصابة باستحاضة شديدة، فأمرها بالجمع، وقال لها: إنه خير الأمرين، قال العلماء: إذا كانت الاستحاضة تسوغ الجمع؛ لأنها متعبة ونوع من المرض؛ فهكذا الأمراض الأخرى التي يشق معها الصلاة كالحمى ونحوها، فإذا جمع فلا بأس.","link":"https://binbaz.org.sa/fatwas/3523/ادلة-جمع-المريض-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1827.mp3","categories":["صلاة المريض"]},{"id":7498,"question":"سؤاله الأخير يقول: ما حكم من ترك خمس صلوات لعذر؛ كعدم الطهارة مثلاً، وكيف يقضي هذه الصلوات، وكيف تقضى إذا كانت أكثر من خمس صلوات، وكذلك كيف تقضى إذا كانت أقل؟ أفيدونا جزاكم الله خير الجزاء.","title":"حكم ترك الصلاة لعذر وكيف تقضى","answer":"الجواب: كثير من المرضى قد يجهل الحكم الشرعي في الصلاة فيتساهل ويؤخر الصلوات، يرجو بزعمه أنه يعني: يشفى حتى يقضيها على حال أحسن، وهذا غلط، لا يجوز للمريض أن يؤخر الصلوات بل يصليها على حسب حاله، فإن الرسول ﷺ قال لـعمران لما اشتكى مرض البواسير، قال: صل قائماً،، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً» فأمره ﷺ بأن يصلي على حسب حاله ولم يسمح له بالتأخير؛ ولأن الصلاة واجبة في وقتها فلا يجوز تأخيرها عن وقتها، لكن يجوز له الجمع بين الظهر والعصر، بين المغرب والعشاء لمرض، كما يجمع المسافر، أما تأخيرها عن وقتها بالكلية، تأخير مجموعتين عن وقتهما وتأخير الفجر عن وقتها، هذا لا يجوز، بل يجب عليه أن يصلي في الوقت ولو على جنبه ولو مستلقياً؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. والنبي عليه السلام يقول: إذا أمرتكم بأمر فأتوا منه ما استطعتم فينبغي التنبه لهذا وتنبيه الناس على هذا الشيء، ينبغي لكل مؤمن ولكل مؤمنة التنبه لهذا الأمر وتنبيه الناس على هذا الأمر، وأن المريض لا يجوز له التأخير بل يجب عليه أن يصلي الصلاة في وقتها، سواء كان قائماً، أو قاعداً، أو على جنبه، أو مستلقياً، على حسب قدرته: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nوإذا عجز عن الصلاة بالماء صلى بالتيمم، كأن يشق عليه استعمال الماء لأجل المرض استعمل التيمم، يعني: تيمم بالتراب تعفر بالتراب، يضرب التراب بيديه فيمسح بهما وجهه وكفيه، ويقوم مقام الماء عند العجز عن الماء، أو عند العجز عن استعماله لمرض والحمد لله، وهكذا لو كانت ملابسه، أو كان فراشه فيه نجاسة، ولم يتيسر له غسل الملابس ولا إبدالها، ولم يتيسر له غسل الفراش ولا إبداله، يصلي على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وصلاته صحيحة، لكن لو أخر جهلاً منه فإنه يقضيها بالترتيب ولو في لحظة واحدة، يقضيها بالترتيب؛ يصلي الفجر الظهر العصر المغرب العشاء مرتبة، ولو صلاها في وقت واحد في الحال فهذا طيب، فالمقصود الواجب عليه البدار والمسارعة إلى القضاء ولا يؤخر ولا يؤجل بعدما يقوى على ذلك.","link":"https://binbaz.org.sa/fatwas/4459/حكم-ترك-الصلاة-لعذر-وكيف-تقضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_007/00703.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":7773,"question":"هذا يقول: أنا رجل مريض بداء السكري، وآخذ عنه علاج، وأحياناً ينزل السكر تحت المعدل ثم أصاب بإغماء في النوم، وإذا قمت ما أدري هل أنا في اليوم الذي نمت فيه أو بعده بيوم، فأسأل عشيرتي ويخبروني بنفس اليوم الصحيح، فأصلي مجتهداً، ولكني لا أضبط صلاتي من حيث عدد الركعات، فهل هذه الصلوات صحيحة أو أعيدها إذا صحيت جداً، وشكراً (س. م. ت) الرياض؟","title":"حكم من فاتته الصلاة بسبب الإغماء","answer":"الجواب: الواجب على من يصاب بالإغماء أنه إذا انتبه واستيقظ وزال إغماؤه يقضي، إذا كان مدة الإغماء قليلة كاليوم واليومين والثلاثة، وقد جاء عن بعض الصحابة أنهم أغموا كـعمار وغيره فقضوا الصلوات، فهو إذا انتبه وزال إغماؤه يقضي ما مضى، لكن لا يعجل حتى يؤول إليه عقله، حتى يعني: يثبت عقله، لا يعجل وهو ما بعد ما ثبت عقله حتى لا يميز بين الركعات، لا، لا يعجل، حتى يعني يستقيم عقله، حتى يستطيع أن يؤدي الصلوات مضبوطة.\nأما إذا أداها وعقله حتى الآن ما يميز بين الركعتين والثلاث، فهو حتى الآن ما بعد استقام عقله، ولا تصح صلاته إنما عليه التأني والتثبت، فإذا أتم حضور عقله واستقام أمره قضى الأيام التي أخبره إخوانه الذين عرفوا حاله أنه ضيعها. نعم.\nالمقدم: لكن بالنسبة لصلواته التي صلاها وهو لم يصح من الإغماء هل يعيدها؟\nالشيخ: يعيدها، نعم الصلوات التي صلاها بدون شعور ما ضبطها يعيدها. نعم.\nالمقدم: وإن كان لا يعلم هل هي ظهر أو عصر؟\nالشيخ: يتحرى بالظن، ويعيد. نعم.\nالمقدم: أحسنتم، أثابكم الله!","link":"https://binbaz.org.sa/fatwas/4980/حكم-من-فاتته-الصلاة-بسبب-الاغماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_046/04603.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":7838,"question":"رسالة وصلت إلى البرنامج من الجمهورية العراقية وباعثها مستمع من هناك، يقول أخوكم في الله (ف. ع. ر)، أخونا رسالته مطولة تشكو من حالة هو فيها، ذلكم أنه وقع له حادث سيارة وأفقده السيطرة على نفسه نتيجة إصابته بالشلل النصفي.الشيخ: أعد أعد.المقدم: أخونا رسالته مطولة في الواقع تصف حاله بأنه أصيب بحادث سيارة، وذلكم الحادث أفقده السيطرة على نفسه لأنه أصيب بشلل نصفي، وهو في الحالة هذه يسأل سماحة الشيخ عن الوضوء، وعن الصلاة، وعن قراءة القرآن كيف يكون حاله؟ جزاكم الله خيرا.","title":"صفة صلاة المريض وطهارته","answer":"الجواب: يعمل بقوله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وقول النبي ﷺ: إذا أمرتكم بأمر فأتوا منه ما استطعتم، فإذا كان أصابه الشلل وأفقده القيام فإنه يصلي على حسب حاله، يصلي قاعداً، ويركع ويسجد إذا استطاع ذلك وهو قاعد، مثلما قال النبي ﷺ لـ عمران بن حصين : صل قائماً، فإن لم تستطع فقاعدا، فإن لم تستطع فعلى جنب خرجه البخاري رحمه الله في الصحيح، وخرجه النسائي بزيادة : فإن لم تستطع فمستلقيا هذا هو الواجب فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وإذا عجز عن الماء تعفر بالتراب تيمم، إذا كان معه مرض يضره الماء تعفر بالتراب يحضر له التراب ويضرب التراب بيديه، ويمسح به وجهه وكفيه عند الحاجة، وله الجمع إذا شق عليه أن يصلي كل صلاة في وقتها فله الجمع بين الظهر والعصر وبين المغرب والعشاء كسائر المرضى.\nأما ما يتعلق ..... الدبر والقبل فهذا يكفيه مسحها بالمناديل ونحوها ولا حاجة إلى الماء، فإن استعمل الماء وقدر على الماء فلا بأس، الماء أكمل وأفضل، فإذا لم يتيسر له ذلك فإنه يستعمل الاستجمار، بالمناديل، بالحجارة، باللبن، والمناديل أرفق به، فيستعمل المناديل الخشنة الطاهرة يمسح بها الدبر والذكر عن البول وعن الغائط ثلاث مرات، فإن لم تكف زاد رابعة وخامسة إلى آخره، والأفضل أن يقطع على وتر إذا زاد رابعة وكفت استحب له أن يزيد خامسة حتى يكون استجمار على وتر، وإذا لم تكف الخامسة زاد سادسة وإذا كفت السادسة استحب أن يزيد سابعة حتى يقطع على وتر، والمهم أنه يستعمل من المناديل ونحوها ما يزيل الأذى، بشرط أن يكون ثلاث فأكثر لا ينقص عن ثلاث؛ لأنه صلى الله عليه وسلم «نهى أن يستجمر بأقل من ثلاث»، فإن كفت الثلاث في إزالة الأذى في الدبر والقبل فالحمد لله، وإن لم تكف زاد حتى يزول الأذى، والأفضل أن يقطع على وتر خمس أو سبع وهكذا ولا حاجة إلى الماء حتى ولو قدر على الماء الاستجمار يكفي لكن الماء أفضل، فإن جمع بينهما يعني: استطاع أن يجمع بينهما فأزال الأذى بالمنديل أو بالحجر ثم استنجى بالماء فهذا خير إلى خير وهذا أكمل وأفضل، ولكن كل واحد يكفي، الماء وحده ... يكفي، والاستجمار وحده يكفي حتى من الصحيح، نعم.\nالمقدم: جزاكم الله خيرا، وكونه لا يستطيع البقاء على وضوء ربما ولا الوقت الكافي لأداء الصلاة شيخ عبد العزيز ؟\nالشيخ: يتقي الله ما استطاع، يتوضأ لكل صلاة، فإذا كان معه سلس أو يعني أصابه لما أصابه الشلل انطلق يعني: الدبر أو انطلق الذكر ... فصار لا يستطيع فإنه يصلي على حسب حاله، لكن يتوضأ لوقت كل صلاة، إذا دخل وقت الظهر يستنجي ويتوضأ وضوء الصلاة أو يتيمم على حسب طاقته ثم يجمع بين الصلاتين، وهكذا المغرب والعشاء.\nالمقدم: يجمع بين الصلاتين.\nالشيخ: إذا شق عليه.\nالمقدم: إذا شق عليه.\nالشيخ: لأجل المرض، وإن كان ما شق عليه فإنه يصلي كل صلاة في وقتها.\nالمقدم: جزاكم الله خيرا.\nالشيخ: والمستحاضة مثل المستحاضة وصاحب السلس العاجز عن الجماعة عن حضور الجماعة مثله يصلي جمعاً إذا شق عليه كل صلاة في وقتها وهو أرفق به، وإن صلى كل صلاة في وقتها فلا بأس. نعم.\nالمقدم: جزاكم الله خيرا.\nالشيخ: أما الرجل لا، يصلي مع الجماعة إذا كان يستطيع.\nالمقدم: إذا كان يستطيع.\nالشيخ: يصلي مع الجماعة ويتوضأ لوقت كل صلاة.\nالمقدم: جزاكم الله خيرا، بالنسبة لقراءة القرآن.\nالشيخ: يقرأ القرآن، إذا توضأ يقرأ القرآن من المصحف.\nالمقدم: وإن انتقض الوضوء؟\nالشيخ: إلى الوقت الآخر، ما بين الوقتين يقرأ القرآن وإن انتقض وضوءه.\nالمقدم: وإن انتقض الوضوء.\nالشيخ: إذا كان صاحب سلس مستمر ......\nالمقدم: نعم نعم.\nالشيخ: إذا توضأ للظهر يقرأ إلى العصر، وإذا توضأ للمغرب يقرأ إلى العشاء، كما يصلي.\nالمقدم: كما يصلي.\nالشيخ: لو تطوع بين الظهر والعصر أو تطوع بين المغرب والعشاء ولو خرج معه البول لأنه عاجز، فهو مثل المستحاضة سواء بسواء، يصلي ويقرأ ما بين الوقتين، نعم.\nالمقدم: الواقع هذا يسر قد يغفل عنه كثير من الناس.\nالشيخ: هذا من تيسير الله هذا من تيسير الله والحمد لله.\nالمقدم: حبذا لو تفضلتم بكلمة حول يسر الإسلام في مثل هذه الأحكام شيخ عبد العزيز ؟\nالشيخ: الله عز وجل يقول سبحانه في كتابه العظيم: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185]، ويقول عز وجل: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]، فمن رحمة الله سبحانه وتعالى أن صاحب السلس وهو البول الدائم أو الريح الدائمة، وهكذا المستحاضة التي معها الدم الدائم ما يقف عنها غير دم الحيض ... دم دائم يقال له: الاستحاضة هؤلاء وأشباههم لهم الجمع بين الصلاتين، ويكفيهم الوضوء لوقت كل صلاة، من تيسير الله إذا دخل وقت الظهر يتوضأ لوقت الظهر ويصلي ..... العصر ويتوضأ لوقت العصر، وهكذا المغرب والعشاء، يعني كل صلاة يتوضأ لوقتها لأن حدثه دائم، سلس أو ريح أو استحاضة ونحو ذلك، وما بين الوقتين يصلي فيه ما شاء، ويقرأ القرآن، ويطوف .... في مكة ولا حرج في ذلك؛ لأنه معذور فصار في حكم الطاهرين والطاهرات ما بين الوقتين؛ لأن الرسول ﷺ أمر المستحاضة بذلك في قصة حمنة وغيرها، وكذلك ما يتعلق بالصوم يفطر ويقضي بعد ذلك المريض إذا عجز عن الصوم وشق عليه المرض، وهذا من يسر الشريعة، وهكذا المسافر يفطر في السفر ويقضي بعد ذلك، كل هذا من لطف الله، وهكذا المرضع إذا شق عليها الصيام، والحامل إذا شق عليها الصيام أفطرتا وقضتا بعد ذلك، نعم.\nالمقدم: جزاكم الله خيرا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/5229/صفة-صلاة-المريض-وطهارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/05209.mp3","categories":["صلاة المريض"]},{"id":7986,"question":"هذه الرسالة يقول مرسلها: أنني لا أستطيع الصلاة بسبب مرضي في المعدة من الهواء أنني أتوضأ في كل صلاة وأكثر الأحيان فإني أصلي وأنقض الوضوء من نصف الصلاة، فأكمل الصلاة، هل الصلاة صحيحة أم لا؟","title":"صلاة صاحب الحدث المستمر","answer":"الجواب: ما دام الحدث مستمراً فأنت في حكم صاحب السلس فصلاتك صحيحة، ولو خرجت الريح، مثل صاحب السلس، الذي يخرج منه الماء، والمستحاضة التي يخرج منها الدم دائماً، تتوضأ في الوقت أيها السائل، ثم تصلي على حسب حالك ما دام الشيء مستمراً معك، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ولو خرج في الصلاة، ولو خرج في الوقت، ما دام توضأت في الوقت، ثم صليت كما أمر الله فخروج هذه الريح منك وأنت تصلي أو قبل الصلاة أو بعد الصلاة لا يضر ما دام مستمراً في حكم المستمر، مثل خروج الدم من المستحاضة التي يستمر معها الدم في غير وقت الحيض، مثل خروج البول من صاحب السلس الذي استمر معه وليس له حيلة، هذا معذور فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5548/صلاة-صاحب-الحدث-المستمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_073/07308.mp3","categories":["صلاة المريض"]},{"id":8033,"question":"أيضاً تقول في رسالتها: ما حكم أو ما الحكم في الفروض التي فاتت من المدة التي ذكرت لكم، أفيدوني وفقكم الله؟","title":"حكم من ترك عدة صلوات اعتقادًا بسقوطها لمرضه","answer":"الجواب: الواجب أن تصلي، الواجب على السائلة أنها تصلي دائماً؛ لأن منع الماء ما يمنع الصلاة، فإذا كانت ضيعت بعض الفروض فعليها قضاؤها؛ لأن الماء إذا لم يتيسر يصلي المسلم بالتيمم، يضرب التراب ويمسح وجهه وكفيه بنية الطهارة من الأحداث الصغرى والكبرى ويصلي، وليس له عذر في ترك الصلاة بسبب عدم الماء، الحمد لله الماء له بدل والبدل هو التيمم كما قال جل وعلا: وَإِنْ كُنتُمْ مَرْضَى أَوْ عَلَى سَفَرٍ أَوْ جَاءَ أَحَدٌ مِنْكُمْ مِنَ الْغَائِطِ أَوْ لامَسْتُمُ النِّسَاءَ فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا [النساء:43].\nفالمسلم إذا عجز عن الماء يتيمم الصعيد الطيب ويصلي هذا هو الواجب على المريض وفاقد الماء التيمم، فيتيمم ويصلي ما وجب الله عليه، فإذا كنت -أيها السائلة- قد فرطت في شيء من الصلوات فعليك أن تصلي ما فرطت فيه.. جميع الأوقات التي تركتي عليك أن تصليها جميعاً أن تقضيها. نعم.","link":"https://binbaz.org.sa/fatwas/5654/حكم-من-ترك-عدة-صلوات-اعتقادا-بسقوطها-لمرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08003.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":8037,"question":"هذه رسالة وردتنا من المرسلة (ن. ع. ح) من بلاد بني الحارث قرية الشباشبة، تقول: فضيلة الشيخ! السلام عليكم ورحمة الله وبركاته وبعد أفيد فضيلتكم بأنني قد أصبت بمرض وأجري لي عملية بالمستشفى، وعند خروجي من المستشفى أفادني الدكتور المختص بأنه يجب علي عدم الغسل بالماء لمدة خمسة شهور بما فيها شهر رمضان المبارك، تقول: وأرجو إفادتي هل أبقى على ما قال الدكتور خمسة شهور أم أغتسل وأصلي وأصوم رمضان؟","title":"كيفية صلاة المريض إذا منع من استعمال الماء","answer":"الجواب: الواجب هو الأخذ بالتعاليم في هذا؛ لأن المرض الذي فيه عملية وجراحات قد يتأثر بالماء، فإذا أوصى الطبيب المختص بعدم استعمال الماء فلا بأس رخصة لك هذه رخصة في ترك الماء واستعمال التيمم ويكفي هذا، التيمم كافي، فإذا جاء وقت الصلاة يتيمم الإنسان ويصلي تضربين التراب بيديك وتمسحين وجهك وكفيك للصلاة ويكفي هذا، ولا تغتسلي بالماء حتى تمضي المدة التي قررها الطبيب.\nأما الصوم فإن كان نهاك عن الصوم قال: إنه يضرك. فلا تصومي وتقضين بعد ذلك، وإن كان ما قال لك عن الصوم شيء فإنك تصومين، تصومي رمضان مع الناس.\nفالحاصل أن الطبيب معتمد في هذه المسائل إذا كان الطبيب ثقة وهو مختص في المسائل ومعروف فإنه يعمل بقوله في هذه المسألة في ترك الماء وفي ترك الصيام؛ لأن المريض قد يضره الصوم وقد يضره الماء، والطبيب المختص هو الذي يعرف هذه الأشياء فإذا قرر على المريض أنه لا يستعمل الماء أو لا يصوم فلا مانع من العمل بذلك، يعمل بذلك حفاظاً على صحته وربنا عز وجل هو أرحم الراحمين سبحانه وتعالى وقد رحم عباده وأذن لهم في ما ينفعهم وترك ما يضرهم، فجعل المريض والمسافر يفطران شرع للمريض والمسافر الفطر حفظاً لصحة المريض وتسهيلاً على المسافر فإنه قد يعتريه المشقة، فالله سبحانه وتعالى أرحم الراحمين، فالذي سامح المريض ورخص له في الإفطار لئلا يضره الصوم كذلك كونه يدع الماء لئلا يضره الماء، الحكم واحد، وهكذا إذا ضره الصوم بنص القرآن. نعم.","link":"https://binbaz.org.sa/fatwas/5653/كيفية-صلاة-المريض-اذا-منع-من-استعمال-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08002.mp3","categories":["صلاة المريض"]},{"id":8080,"question":"هذه الرسالة وردتنا من المستمع (ش. ع. ش) من الطائف يقول: والدي عمل عملية بالمستشفى وجلس في المستشفى أكثر من خمسة عشر يوم، ولم يصل أربع وأربعين فرض كانت قبل العملية، وقد اشتد عليه الوجع ولم يصل تلك الأربعة، وأما أربعين الفرض فهو كان في حالة بنج ولا يتمكن من الطهارة الكاملة التي تمكنه من أداء الصلاة. لذا أرجو إرشاده عن القضاء والكفارة، ماذا تقولون في ذلك وفقكم الله؟","title":"حكم المريض إذا ترك الصلاة أثناء مرضه","answer":"الجواب: إذا مات الميت وعليه صلوات لا تقضى عنه، ما شرع الله القضاء ولكن ينبغي لأهل المريض أن يلاحظوا تنبيهه على الصلاة، ويصلي على حسب حاله قاعداً أو قائماً أو على جنبه أو مستلقياًَ مثل ما أمر النبي ﷺ عمران بن حصين قال: صل قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً.\nفينبغي لأهل المريض أن يلاحظوا هذا ويشجعوا المريض ويوجهوه ويعلموه حتى يصلي على حسب حاله في المرض ولو كانت ملابسه نجسة إن تيسر غسلها أو إبدالها بغيرها فالحمد لله وإلا صلى على حسب حاله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16] وهكذا الفراش يصلي عليه ولو كان نجساً فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16] لكن إذا تيسر تغيير الفراش تغيير الملابس بشيء طاهر فهذا واجب، وإذا ما تيسر صلى على حسب حاله ولو ما توضأ ولو كانت الثياب فيها نجاسة وهكذا الفراش، وإن قدر على الوضوء أو التيمم وجب عليه ذلك، بدل الوضوء يحضر عنده الماء وتوضأ، وإن لم يقدر على استعمال الماء يحضر عنده بعض التراب حتى يتيمم، يتعفر يعني بوجهه وكفيه كما هو معروف، وإذا عجز عن هذا وعن هذا ولم يتيسر صلى على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16].\nولكن كثيراً من الناس لا يبالون بهذه المسائل، يتركون المريض، والمريض ربما يتأول أنه قد اشتد به المرض وأنه سوف يفعل إذا خف عليه المرض، وقد يأتيه الموت ولا يفعل، فلا ينبغي هذا بل يجب أن المريض يصلي على حسب حاله بالماء أو بالتيمم قائماً أو قاعداً أو على جنبه أو مستلقياً حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُم [التغابن:16] هذا هو الواجب، أما إذا كان شعوره قد تغير كأن أصابه ما يغير عقله فلا صلاة عليه، إذا تغير العقل فلا صلاة عليه، لكن مادام عقله معه فعليه الصلاة، وإذا أخذ البنج وتأخر صحوه من البنج يوماً أو يومين فهذا مثل النائم إذا استيقظ يصلي ما ترك.\nأما إذا كان أصابه خلل في عقله بأن اختل عقله بسبب المرض ومضى عليه مدة طويلة فهذا لا شيء عليه، لا قضاء عليه لو صح بعد ذلك، وإن قضى احتياطاً حسن، لكن لا قضاء عليه على الصحيح إذا طالت المدة، أما إن كانت المدة يوم يومين ثلاث فيقضي بعد أن يصحو من غشيته وذهاب عقله.\nوعلى كل تقدير لا تقضى عنه الصلاة سواء تعمد ذلك لجهله أو لعلة من العلل، فلا تقضى الصلاة إنما يقضى الصوم، إذا مات وعليه صيام قد فرط في قضائه يقضى عنه، أما إذا مات وعليه صيام ما تمكن من قضائه، مات في مرضه وما تمكن من قضاء الصوم فلا صوم عليه، لكن بعض الناس قد يصحو من مرضه قد يشفى ثم يتأخر ولا يقضي ما عليه من صيام رمضان، فهذا يقضى عنه، يقضي عنه أولياؤه؛ ورثته. نعم. كما قال النبي عليه الصلاة والسلام: من مات وعليه صيام صام عنه وليه، وقد سئل عدة أسئلة عليه الصلاة والسلام، قال بعض السائلين: يا رسول الله! إن أمي ماتت وعليها صيام شهر؟ وآخر يقول: إن أبي مات وعليه كذا؟ فيقول: صم. فيأمرهم بالصوم، ويقول لهم: أرأيتم لو كان على أبيك أو كان على أمك.. لو كان على أختك دين أكنت قاضيه؟ فاقضوا الله، فالله أحق بالوفاء فيشبه ما عليه من الصوم بالدين، فهو يأمر أولياءهم بالقضاء، أما الصلاة فلم يأمر أحداً بقضائها عليه الصلاة والسلام. نعم.\nالمقدم: لكن بالنسبة للصيام أليس مثلاً خاص برمضان أو في كل صيام؟\nالشيخ: الصواب أنه عام، بعض أهل العلم يخصه بالنذر ويقول: هذا في النذر خاصة، ولكنه قول ضعيف، والأحاديث عامة في رمضان وفي غيره؛ صوم رمضان وصوم الكفارة فهذا يقضي عنه أولياؤه. نعم.","link":"https://binbaz.org.sa/fatwas/5881/حكم-المريض-اذا-ترك-الصلاة-اثناء-مرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_085/08505.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":8173,"question":"الرسالة التالية باعثها أخونا ناصر البريدي من المنطقة الشرقية يقول: أنا كنت مريض في المستشفى راقد سرير كما يقول حوالي أسبوع، واشتد علي المرض لم أستطع أصلي، لكن بعدما طلعت من المستشفى صليت كل الأوقات التي فاتتني في عصر، وصليتها قصراً من كل وقت ركعتين ركعتين هل صلاتي هذه صحيحة أم لا؟","title":"حكم من ترك عدداً من الصلوات بسبب مرضه","answer":"الجواب: أولاً الواجب عليك أن تصلي في حال المرض ولو أنك جالس أو مضطجع، تصلي على حسب حالك لأن الله سبحانه يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والنبي ﷺ قال للمريض صل قائما، فإن لم تستطع فقاعدا، فإن لم تستطع فعلى جنب، فإن لمم تستطع فمستلقيا  هكذا أمره النبي عليه الصلاة والسلام، فالمريض يفعل ما يستطيع إن استطاع قائماً صلى قائماً، وإن عجز صلى قاعداً، وإن عجز صلى على جنبه الأيمن أو الأيسر والأيمن أفضل، فإن عجز صلى مستلقياً ورجلاه إلى القبلة هذا هو المشروع، فإذا لم يفعل وجب عليه القضاء، لم يفعل بزعمه أنه يصلي بعد حين أكمل أو كونه يشق عليه حال وجود المرض فكل هذا غلط ولكن عليه القضاء، لأنه تركها بشبهة فعليه القضاء والمبادرة بالقضاء إذا استطاع ذلك ويصلي أربعاً ما يصلي ثنتين، ثنتين هذه للمسافر، أما المريض يصلي أربع ولا يصلي ثنتين، إنما قصر الصلاة للمسافرين خاصة؛ أما المرضى فإنهم يجمعون فقط لأن لهم الجمع بين الصلاتين الظهر والعصر والمغرب والعشاء لا بأس يجمعون، أما القصر يعني: كونه يصلي ثنتين فلا، لكن يغتر بعض الناس بما يسمع من بعض العامة يقولون: المريض له يقصر، وقصدهم بالقصر الجمع، يسمون الجمع: قصر وهذا غلط في اللغة، الجمع بين الظهر والعصر والجمع بين المغرب والعشاء ما يسمى قصر يسمى جمعاً، لأنه جمع بين الصلاتين في وقت إحداهما فيسمى جمعاً لا قصرا، أما القصر فهو كونه يصلي الظهر ثنتين والعصر ثنتين والعشاء ثنتين هذا القصر، لكن بعض العامة يسمي الجمع قصر فنتج عن هذا أن بعض الناس قصر في المرض لما يسمع من بعض العامة أن المريض يقصر، ومرادهم أنه يقصر يعني: يجمع هذا لغة العامة، يسمون الجمع قصراً وهو غلط في اللغة العربية، الجمع ما يسمى: قصراً، يسمى: جمعاً، فإذا صلى الظهر والعصر جميعاً في وقت الظهر أو في وقت العصر هذا يسمى جمع ما يسمى قصر، وهكذا إذا صلى المغرب والعشاء جمعاً في وقت المغرب أو في وقت العشاء هذا يسمى جمعاً لا قصرا، أما القصر فكونه يصلي العشاء ثنتين، الظهر ثنتين، العصر ثنتين هذا القصر وهذا خاص بالمسافرين، المسافر هو الذي يصلي ركعتين، أما المريض فعليه أن يصلي أربعاً لكن له أن يجمع بين الظهر والعصر وله أن يجمع بين المغرب والعشاء من أجل المرض والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/5978/حكم-من-ترك-عددا-من-الصلوات-بسبب-مرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_104/10410.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":9113,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المرسل (ص.ع. م.) أخونا يقول: أنا شاب أبلغ من العمر السادسة والعشرين حصل لي حادث منذ ثلاث سنوات، ومن بعدها لم أستطع أن أتحكم بالخروج، مع ذلك حصل لي أيضًا شلل نسبي، هل يجوز لي أن أقرأ القرآن وأصلي بالتيمم، وهل يصلح التيمم على جدار المنزل؟","title":"الواجب على من لا يستطيع استمساك البول","answer":"الجواب: هذا السؤال مجمل، فإذا كان مراد السائل أنه لا يستمسك البول فإنه يصلي على حسب حاله، ويصلي بماء ما هو بالتيمم، وهكذا إذا أصابه الشلل فصار لا يستمسك بوله بل يخرج فإنه يستنجي إذا دخل الوقت يتوضأ إذا دخل الوقت، مثل المستحاضة إذا دخل الوقت استنجى وتوضأ للصلاة ثم صلى ولو خرج شيء فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nلكن يتحفظ بأن يعصب على ذكره شيئًا حتى يخفف عنه النجاسة، كالمستحاضة تجعل في فرجها شيء يسد الدم في وقت الاستحاضة، وهو الدم الذي يجيء معها دائمًا غير الحيض، فهذا والمستحاضة وأشباههم الواجب عليهم أنهم يستعملون ما يخفف الخارج قطن ونحوه ويتوضأ الواحد منهم إذا دخل الوقت يستنجي ثم يتوضأ وضوء الصلاة ثم يصلي على حسب حاله، وإذا كان معه ما يمنع الوضوء بأن معه مرض يشق معه الماء فإنه يتيمم، يضرب التراب بيديه أو الجدار الذي فيه تراب يحكه ويضرب التراب ويمسح به وجهه وكفيه، إذا كانت الجدار جدار لبن إذا حكه وفيه غبار ضربه وإلا ضرب الأرض، هذا إذا عجز عن الماء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7273/الواجب-على-من-لا-يستطيع-استمساك-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17907.mp3","categories":["صلاة المريض"]},{"id":9266,"question":"أحد الإخوة المستمعين يقول: (ح. ع. س) من الرياض يسأل ويقول: زوجتي في شهرها الأخير حين كتبت الرسالة ولا تستطيع الوقوف للصلاة حيث أن وضع الركوع والسجود يسبب لها آلاماً كبيرة ولا تستطيع أيضاً الصلاة جالسة، فهل يحق لها الصلاة على هيئة أخرى، نرجو أن تفيدونا جزاكم الله خيراً؟","title":"كيفية صلاة العاجز عن القيام والقعود","answer":"الجواب: ثبت عن رسول الله عليه الصلاة والسلام أنه قال لـعمران بن الحصين لما اشتكى: صل قائماً فإن لم تستطع فقاعداً فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً والله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، فجميع بني آدم في هذا سواء الرجل والمرأة، إذا عجز الرجل أو المرأة عن الصلاة قائماً أو قاعداً صلى على حسب حاله على جنبه الأيمن أو جنبه الأيسر أو مستلقياً حسب قدرته، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، ويعمل الأعمال بالنية إذا كان على جنبه أو مستلقياً يعمل بالنية، بنية القيام فيستفتح الصلاة ويتعوذ بالله من الشيطان ويسمي ويقرأ الفاتحة وما تيسر معها، ثم ينوي الركوع ويكبر فيقول: سبحان ربي العظيم، سبحان ربي العظيم، ثم ينوي الرفع فيقول: سمع الله لمن حمده ربنا ولك الحمد.. إلى آخره، ثم ينوي السجود فيكبر ويسجد، وهكذا. نعم.","link":"https://binbaz.org.sa/fatwas/7429/كيفية-صلاة-العاجز-عن-القيام-والقعود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15404.mp3","categories":["صلاة المريض"]},{"id":9336,"question":"تسأل أيضاً وتقول: في صلاتي لا أستطيع أن أقف أصلي وأنا جالسة بسبب مرض في رأسي وهو يؤلمني، فتسأل عن حكم ذلك؟","title":"حكم صلاة المريض جالسا","answer":"الجواب: إذا عجز المريض عن القيام في الصلاة جاز له أن يصلي قاعداً، وإذا عجز عن القعود جاز له أن يصلي على جنبه، وإذا عجز على الجنب صلى مستلقياً فالأمر بحمد لله واسع، والله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ويقول النبي ﷺ لـعمران بن حصين لما كان مريضاً: صل قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً .\nفأنت أيها الأخت في الله! تعملي ما تستطيعين، إن استطعت القيام فقومي، وإن عجزت بسبب الدوخة أو بسبب الضعف الذي بك صلي قاعدة، وهكذا لو عجزت عن القعود صلي على جنبك والأفضل الأيمن، فإن عجزت عن الجنب صلي مستلقية، ورجلاك إلى القبلة، هذا هو المشروع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7506/حكم-صلاة-المريض-جالسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23804.mp3","categories":["صلاة المريض"]},{"id":9498,"question":"هذه رسالة وردت إلينا من المرسل الحاج جوده السيد الخزامي مصري الجنسية مقيم بالمدينة المنورة، يقول: لي جدة تبلغ من العمر مائة سنة أو تزيد، وكانت تصلي وتقوم بحق الله على الوجه الأكمل من صيام وصلاة، فلكن لما بلغت الكبر تركت الصلاة بعذر كبر السن، علماً بأن وزنها ثقيل، وتطلب مني أن أسقط عنها الصلاة، فهل يجوز ذلك؟","title":"حكم ترك الصلاة بسبب كبر السن","answer":"الجواب: لابد من النظر في أمرها، إن كان عقلها معها لم يتغير عقلها فلابد من الصلاة، ولا تسقط عنها الصلاة، وليس لك ولا لغيرك إسقاط الصلاة عنها، هذا أمر لله، ليس حقاً للناس، فعليها أن تصلي، وإذا كانت عاجزة ثقيلة شبه المريضة يشق عليها العمل صلت الظهر والعصر جميعاً، والمغرب والعشاء جميعاً كسائر المرضى، أما إذا كانت تستطيع أن تصلي كل صلاة في وقتها فإنه يلزمها كسائر المسلمين، وكبر السن لا يمنعها من ذلك إذا كانت بعافية، فعليها أن تصلي الظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، والفجر في وقتها، لكن إذا اشتد بها الأمر لثقلها وكبر سنها وضعفها جاز لها أن تجمع بين الظهر والعصر وبين المغرب والعشاء كالمرضى، أما ترك الصلاة فلا يجوز، يجب عليها أن تصلي وأن تستعين بالله، وأن تراقب الله وتخشاه ولاسيما في هذا السن قد دنت من الأجل، فالواجب عليها أن تعد العدة الصالحة عند لقاء ربها، وليس لها أن تتساهل بالصلاة لا بالليل ولا في النهار، ولكن تتقي الله ما استطاعت، إن كانت تستطيع القيام صلت قائمة، فإن كانت تعجز عن القيام صلت قاعدة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] يقول النبي ﷺ للمريض: صل قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً فإذا كانت تعجز عن الصلاة قائمة صلت وهي جالسة، والله نسأل أن يعينها على الخير. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7658/حكم-ترك-الصلاة-بسبب-كبر-السن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24201.mp3","categories":["صلاة المريض","حكم الصلاة وأهميتها"]},{"id":9702,"question":"وهذه رسالة وردت من حائل من خميس سليم المطلق يقول في رسالته: والدتي امرأة مسنة تقارب الثمانين عاماً، والمشكلة أنها تركت الصلاة لأسباب قاهرة منها: أنها لا تستطيع القيام لكبر سنها.ثانياً: هي مصابة بشلل شامل في جميع جسمها، وجميع مفاصلها وأعضائها تنتابها رعدة.كذلك لا تستطيع الصلاة قاعدة ولا على جنب، ولا في يدها، ولا بأصابعها؛ لأنها كما قلت لكم: تهتز وحتى رأسها، علماً أنها لا تستطيع أن تطعم نفسها بل نحن الذين نقوم بإطعامها، وكذلك لا تستطيع أن تغسل أي عضو من أعضائها.أما من ناحية الإحساس والشعور والعقل فهي سليمة، وهي تركت الصلاة من مدة طويلة عندما اشتد عليها هذا المرض فما الحكم في ذلك بارك الله فيكم؟","title":"حكم صلاة المصاب بالشلل الكامل وطهارته","answer":"الجواب: ما دامت بهذا الوصف شعورها معها وعقلها معها، فالواجب عليها أن تصلي على حسب حالها، قاعدة، أو على جنب، أو مستلقية، تعلم وتوجه إلى الخير، وتعلم وتصلي على حسب حالها بالنية، بالنية والكلام، وتقول: الله أكبر، وتقرأ الفاتحة وما تيسر معها، ثم تقول: الله أكبر تنوي الركوع وتقول: سبحان ربي العظيم، سبحان ربي العظيم، ثم تقول: سمع الله لمن حمده ناوية للرفع، ربنا ولك الحمد إلى آخره، ثم تكبر ناوية السجود وتقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم تكبر ناوية الرفع من السجدة الأولى، وتقول: رب اغفر لي رب اغفر لي، ثم تكبر ناوية السجدة الثانية تقول: سبحان ربي الأعلى، ثم تكبر رافعة ناوية الرفع من الركعة الأولى، فتقرأ الفاتحة وما تيسر معها، ثم تكبر بنية الركوع وهكذا، وهي على فراشها قاعدة أو على جنبها، أو مستلقية؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nولو كانت بها رعدة، ولو كان بها شلل حسب طاقتها، النية موجودة في القلب، فتعمل بالنية وبالكلام ويكفيها ذلك.\nأما الوضوء فلا يلزمها الوضوء لعجزها، فإن تيسر من يوضيها، من يغسل وجهها ويديها ويمسح رأسها ويغسل رجليها من بناتها وبعض الخادمات، طيب، فإن لم يتيسر هذا تيمم يؤتى لها بالتراب وتوضع يديها فيه، ويمسح وجهها وكفيها، أو بعض القائمين عليها يضع يديه في التراب ويمسح بها وجهها وكفيها بنية الوضوء ويكفي ذلك.\nأما الخارج فيزال عنها بالمناديل، ... الدبر والقبل يزال عنها ... الخادمة أو بنتها أو زوجة ابنها، أو من يتيسر لها من النساء يخدمها يزيل الأذى بالمناديل من دبرها ومن قبلها من البول، وكل ما حصل شيء يزال بالمناديل ثلاث مرات، أو أكثر حتى ينقى المحل، ثم تيمم بعد ذلك للصلاة، وتجمع بين الظهر والعصر والمغرب والعشاء، وتعلم ما دام عقلها معها الحمد لله، ولا يجوز ترك هذا أبداً. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7841/حكم-صلاة-المصاب-بالشلل-الكامل-وطهارته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_252/25202.mp3","categories":["صلاة المريض"]},{"id":10104,"question":"مستمع من المملكة الأردنية الهاشمية في مكتبة الحرمين العلمية يقول: إذا كنت معاقًا إعاقة شديدة ولا أستطيع الحركة كيف لي أن أتوضأ وأصلي؟","title":"كيفية طهارة وصلاة المقعد","answer":"الجواب: عليك أن تصلي وتتوضأ بالعون، تكلف غيرك كزوجتك أو ولدك أو شخص آخر بأجرة ليوضئك يغسل وجهك ويديك و .. إلى آخره ويجمرك بالمناديل عن الأذى والحمد لله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، هذا تأمره أن يزيل الأذى من الدبر والقبل بالجمار بالحصى بالمدر بالمناديل ثلاث مرات فأكثر حتى يزيل الأذى ثم يمضمضك وينشقك ويغسل وجهك ويديك ويمسح رأسك وأذنيك ويغسل رجليك، فإن كان يشق عليك الماء ييممك يمسح وجهك بالتراب ويديك بالتراب بالنية عنك أنت تنوي وهو يعمل والنية منك والعمل منه، هذا هو الواجب عليك وتصلي على حسب حالك، تصلي تكبر بالنية أنه دخلت في الصلاة وتركع بالنية إذا كنت تستطيع الركوع تحني رأسك وأنت واقف وإن كنت لا تستطيع القيام ولا الحركة لا رأسك ولا غيره تنوي نية تكبر وتقرأ ثم تكبر وتنوي الركوع، تقول: سبحان ربي العظيم، ثم تقول: سمع الله لمن حمده إذا كنت وحدك ناويًا الرفع ثم تكبر ناويًا السجود تقول: سبحان ربي الأعلى ثم ترفع ناويًا الجلوس بين السجدتين تقول: رب اغفر لي، ثم تكبر ناويًا السجود تقول: سبحان ربي الأعلى وهكذا تكمل بالنية، بالنية والقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nالمقدم: جزاكم الله خيرًا، إذا لم يجد من يعينه -سماحة الشيخ- كيف يتصرف؟\nالشيخ: يصلي على حسب حاله يصلي بالتيمم إن قدر ...... ولا يخرج يدعه يخرج الوقت يصلي في الوقت ولا يعيد، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، وقد صلى الصحابة بغير وضوء ولا تيمم لما بعثهم النبي ﷺ يلتمسون عقد عائشة ، لم يجدوا ماءً ولم .... يجدوا.\nا لمقدم: ... وقبل مشروعية التيمم.\nالشيخ: قبل مشروعية التيمم وليس عندهم ... نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8273/كيفية-طهارة-وصلاة-المقعد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_333/33315.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":10252,"question":"السؤال الأخير الذي نعرضه لأختنا في هذه الحلقة، تقول: رأيت امرأةً كبيرةً في السن لا تستطيع القيام من فراشها أو الحركة، وهي مصابة بالشلل، سألت نفسي: كيف تتوضأ هذه وكيف تصلي؟ أردت أن أسأل سماحتكم جزاكم الله خيرًا؟","title":"كيف يتطهر ويصلي من أصيب بالشلل وعجز عن الحركة؟","answer":"الجواب: عليها أن تتقي الله ما استطاعت، تتوضأ كما أمر الله، يقرب لها الماء وتتوضأ إذا كانت يداها صالحتين أو يوضئها غيرها كأبيها وأخيها أو أختها أو زوجها؛ لأن الله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].\nأما الاستجمار فينبغي إذا كانت تستطيع بيدها أن تستعمل الحجر أو اللبن أو المناديل حتى تنظف الدبر والقبل من أثر الغائط والبول ثلاث مرات أو أكثر حتى يتنقى المحل من الأذى، ويكفي ذلك عن الماء، فإذا استطاعت أن تفعل هذا بيدها يعني: تطهر محل الغائط بالمناديل حتى تنقي المحل من أثر الغائط ثلاث مرات أو أكثر، لابد من ثلاث فأكثر لا يقل عن ثلاث، وهكذا المسح للقبل ثلاث فأكثر حتى يتنقى المحل من أثر البول، وهكذا الذكر الرجل ولو أنه صحيح ولو أنه سليم ولو أنها سليمة المرأة إذا فعلت هذا يكفي عن الماء، وأما الوجه واليدان والرأس والرجلان فلابد من الوضوء إن استطاعت بنفسها وإلا وضأها غيرها من زوج أو خادم أو أم أو أخت أو نحو ذلك، فإن لم يتيسر لها أحد يوضئها تيممت إن استطاعت، تضرب التراب بيديها وتمسح بهما وجهها وكفيها بنية الطهارة، فإن لم تستطع يممها غيرها أيضًا، تسمح لغيرها تأذن لغيرها ويقوم مقامها، فيضرب التراب بيديه ويمسح بهما وجهها وكفيها بالنية عنها، إذا لم يتيسر من يوضئها.\nفالحاصل أنها تتقي الله ما استطاعت في الوضوء والتيمم بنفسها أو بمن يقوم مقامها إن عجزت.\nوأما الاستنجاء فيكفي الحجارة أو اللبن أو المناديل وليس من اللازم أن تستعمل الماء، فإذا استجمر الإنسان بالحجارة أو باللبن أو بالمناديل ثلاث مرات أو أكثر حتى أنقى المحل كفى ذلك ولو كان صحيحًا، فالمريض من باب أولى. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8423/كيف-يتطهر-ويصلي-من-اصيب-بالشلل-وعجز-عن-الحركة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33605.mp3","categories":["صلاة المريض"]},{"id":10256,"question":"من الرياض المستمع حسن بن هادي بعث يسأل ويقول: إن بعض المرضى لا يؤدون الصلاة المكتوبة أثناء المرض، إما لعدم المقدرة عليها، أو أنه يعطي نفسه الأمل بأن يقضيها بعد الشفاء، هل تصح صلاة المريض الذي لا يستطيع القيام من فراشه بدون وضوء، وأينما كان مولٍ وجهه وهو على فراشه، نرجو الإفادة جزاكم الله خيرًا؟","title":"حكم ترك المريض للصلاة أثناء فترة مرضه","answer":"الجواب: الصلاة واجبة على المريض، صلاة الفريضة الظهر والعصر والمغرب والعشاء والفجر واجبة على المريض حسب طاقته، ولا يجوز له تركها، بل يجب أن يصليها على حسب حاله، لقول النبي ﷺ للمريض الذي سأله: صل قائمًا فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب رواه البخاري في صحيحه، من حديث عمران بن حصين ، ورواه النسائي وزاد: فإن لم تستطع فمستلقيا.\nهذا هو الواجب على المريض أن يصلي قائمًا إن استطاع فإن عجز صلى قاعداً، يركع ويسجد فإن عجز عن القعود صلى على جنبه، يقرأ ويأتي بالأذكار القولية، ويأتي بالأفعال الفعلية بالنية، الركوع بالنية والسجود بالنية، والرفع من الركوع بالنية، والرفع من السجود بالنية، مع الأذكار الشرعية، فإن عجز صلى مستلقيًا على ظهره ورجلاه إلى القبلة، يكبر ويقرأ ثم يكبر ويركع بالنية، ثم يقول: سمع الله لمن حمده بالنية رافعًا من الركوع، ثم يكبر ناويًا السجود يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ثم يكبر ناويًا الرفع من السجود يجلس بين السجدتين بالنية، يقول: رب اغفر لي، رب اغفر لي ، ثم يكبر ناوياً السجدة الثانية وهكذا، لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، وهذه طاقته، وليس له ترك الصلاة، فإن عجز عن الماء تيمم بالتراب بالصعيد التراب يمسح وجهه وكفيه. إذا لم يستطع استعمال الماء، أو ليس عنده من يوضئه. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8427/حكم-ترك-المريض-للصلاة-اثناء-فترة-مرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27907.mp3","categories":["صلاة المريض","حكم الصلاة وأهميتها"]},{"id":10271,"question":"المستمع (خ. ص. ع) من الجماهيرية الليبية بعث برسالة يقول فيها: أنا في السابعة عشرة من عمري، مصاب بسلس البول ولا أستطيع أن أحافظ على صحة وضوئي حتى أتمكن من إتمام الصلاة، كيف تنصحونني جزاكم الله خيرًا؟","title":"حكم المصاب بسلس البول إذا أراد الصلاة","answer":"الجواب: المصاب بالسلس يتوضأ إذا دخل الوقت كالمصابة بالاستحاضة الدم الدائم، فإذا دخل الوقت استنجى وتوضأ وضوء الصلاة، وصلى ولو خرج منه شيء، كما تصلي المستحاضة التي معها الدم الدائم توضأ إذا دخل الوقت، يعني: تستنجي وتتوضأ وضوء الصلاة وتحفظ بشيء، وتصلي جميع الوقت إذا توضأت للظهر تصلي الظهر تصلي النوافل، تقرأ القرآن من المصحف ولو خرج شيء، حتى يأتي الوقت الآخر وهكذا، كلما جاء وقت تستنجي وتتوضأ وضوء الصلاة إذا خرج شيء.\nوهكذا صاحب السلس إذا دخل الوقت توضأ وضوء الصلاة، إذا استنجى وتحفظ بشيء وتوضأ وضوء الصلاة ثم يصلي ما بدا له في الوقت من النوافل حتى يأتي الوقت الآخر، فإذا جاء الوقت الآخر وقد خرج منه شيء يعيد الوضوء، يستنجي ويعيد الوضوء.\nأما لو سلمه الله ولم يخرج شيء فلا إعادة عليه ووضوءه صحيح، ويصلي به الوقت الآخر ولا حرج.\nالمقصود: أنه كالمستحاضة في هذا العمل، يتوضأ لكل صلاة هكذا صاحب السلس إذا كان معه البول الدائم.\nوهكذا المرأة اللي معها الماء الدائم من فرجها، توضأ لوقت كل صلاة كالمستحاضة، إذا دخل وقت الفجر طلع الفجر توضأ للفجر استنجى وتوضأ للفجر، وإذا دخل وقت الظهر زالت الشمس كذلك يستنجي ثم يتوضأ وضوء الصلاة للظهر، ويصلي النوافل إلى العصر، ويقرأ من المصحف كذلك، ثم إذا دخل وقت العصر أعاد الوضوء إذا كان قد خرج شيء، يستنجي ويعيد الوضوء، وهكذا المغرب وهكذا العشاء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8442/حكم-المصاب-بسلس-البول-اذا-اراد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33711.mp3","categories":["صلاة المريض"]},{"id":10547,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من بغداد،وباعثها أحد المستمعين رمز إلى اسمه بالحروف (م. ض. هـ) يقول في أحد أسئلته: إنني رجل كبير في السن ولدي آلام في فقرات الظهر، وبعض الأحيان أؤدي الصلاة وأنا جالس، أفيدوني عن حكم ذلك؟ جزاكم الله خيراً.","title":"صلاة العاجز عن الوقوف","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالله سبحانه يقول في كتابه العظيم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فإذا كنت لا تستطيع الصلاة وأنت قائم فلا حرج، بسبب مرض الظهر لا حرج عليك إذا كان فيه مشقة كبيرة صل جالساً، يقول النبي صلى الله عليه وسلم لـعمران بن حصين لما اشتكى قال له ﷺ: صل قائماً، فإن لم تستطع فقاعداً، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقياً، والله يقول سبحانه: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8720/صلاة-العاجز-عن-الوقوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32101.mp3","categories":["صلاة المريض"]},{"id":10778,"question":"محمد فياض بعث بهذه الرسالة يقول فيها: أصاب رأسي صداع أو يصاب رأسي بصداع أحياناً ويستمر فلا أستطيع أن أصلي إلا صلاة بالإيماء فلا أسجد بسبب هذا الصداع الذي لا أستطيع أن أسجد وأنا مصاب به، فما الحكم جزاكم الله عني خير الجزاء؟","title":"صفة صلاة المريض الذي لا يستطيع السجود","answer":"الجواب: الله سبحانه وتعالى يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول : لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286].\nفمن أصيب في رأسه بمرض يشق عليه معه السجود في الأرض ويضره، لا حرج عليه يومي إيماءً ويكون إيماؤه في السجود أخفض من الركوع ولا حرج عليه، يركع ويسجد بالإيماء ولكن يكون سجوده أخفض من الركوع، يركع في الهواء ويسجد في الهواء ولكن يكون سجوده أخفض من الركوع إذا كان يشق عليه مس الأرض في السجود والسجود على الأرض لمرض في رأسه أو غير ذلك من الأمراض التي تمنعه من السجود. نعم.","link":"https://binbaz.org.sa/fatwas/8961/صفة-صلاة-المريض-الذي-لا-يستطيع-السجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_350/35007.mp3","categories":["صلاة المريض"]},{"id":11196,"question":"مريض يصلي ولا زال يصلي بالتيمم وملابسه وفرشه غير طاهرة؛ لعدم استطاعته الطهارة عند كل صلاة أفتونا مأجورين في حاله؟","title":"حكم صلاة المريض في ملابس غير طاهرة","answer":"الجواب: الواجب عليه أن يطهر ثيابه ومحل صلاته كل وقت، فإذا لم يستطع صلى على حسب حاله، إذا كان ما عنده أحد يطهرها ولا يستطيع هو، فالله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] يصلي على حسب حاله، والتيمم يجوز له إذا كان عاجزًا عن الماء، إذا كان لا يستطيع أن يستعمل الماء يضره الماء، فإنه يتيمم ويكفيه التيمم والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9367/حكم-صلاة-المريض-في-ملابس-غير-طاهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37212.mp3","categories":["صلاة المريض","الطهارة لصحة الصلاة"]},{"id":11245,"question":"هذه رسالة وصلت من مستمع للبرنامج، المستمع رمز لاسمه بـ(أ. أ. أ) يقول: قال الرسول ﷺ في صلاة المريض: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب كيف يصلي المريض على جنبه، وكيف يركع ويسجد مأجورين؟","title":"صفة صلاة المريض","answer":"الجواب:  هذا من رحمة الله جل وعلا وتسيره لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، إذا عجز الإنسان عن الصلاة قائمًا صلى قاعدًا سواءً قعوده متربعًا أو محتبيًا لا فرق في ذلك أي قعود كان يجزيه, لكن الأفضل أن يكون متربعًا، النبي ﷺ كان إذا صلى وهو جالس صلى متربعًا، فإن عجز عن القعود صلى على جنبه والأفضل جنبه الأيمن إذا تيسر وإلا على جنبه الأيسر، فإن عجز صلى مستلقيًا على ظهره ورجليه إلى القبلة، وإذا صلى على جنبه أو مستلقيًا يكبر يقول: الله أكبر، بنية الصلاة تكبيرة الإحرام، ثم يقرأ الفاتحة ويقرأ ما تيسر معها ثم يكبر ناويًا الركوع، الله أكبر ناويًا الركوع، ويقول: سبحان ربي العظيم سبحان ربي العظيم سبحان ربي العظيم ناويًا الركوع، ثم يقول: سمع الله لمن حمده إذا كان إمامًا أو منفردًا، سمع الله لمن حمده ناويًا الرفع من الركوع، ربنا ولك الحمد إلى آخره، ثم يكبر ساجدًا ويقول: سبحان ربي الأعلى سبحان ربي الأعلى بالنية، ثم يكبر رافعًا فيبقى بعض الشيء ... بين السجدتين يقول: رب اغفر لي رب اغفر لي بعد الرفع من السجدة الأولى فيقول: رب اغفر لي وهو على جنبه، ثم يكبر للسجدة الثانية ناويًا السجدة الثانية يقول: سبحان ربي الأعلى سبحان ربي الأعلى وهكذا حتى يتم الصلاة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9426/صفة-صلاة-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29201.mp3","categories":["صلاة المريض"]},{"id":11810,"question":"تقول: بعد انتهاء مدة الحيض أصبت بوعكة صحية أقعدتني في الفراش أي: ما يقارب خمسة أيام، خلال هذه الأيام -أي: الأيام الخمسة التي بعد فترة الحيض- لم أؤد فريضة الصلاة، فهل تعتبر هذه الأيام من فترة الحيض، أم ينبغي علي أن أصلي هذه الأيام التي تركتها، كأن أصلي كل وقت مرتين لمدة خمسة أيام، أم أصليها دفعة واحدة؟ جزاكم الله خيرًا.","title":"حكم من ترك الصلاة لمرض ألم به عدة أيام","answer":"الجواب:  الواجب عليك أن تقضيها، الفرائض التي تركت بعد الطهارة، الواجب أن تقضيها كلها، ولو في وقت واحد إذا استطعت، وإلا فحسب الطاقة، صلي ثلاث صلوات، أربعًا خمسًا، ثم تستريحين، ثم تصلين الباقي، وهكذا، عليك المبادرة والمسارعة، وقد أخطأت في هذا الأمر، فعليك التوبة إلى الله من ذلك؛ لأن المرض ما يمنع من الصلاة، فيصلي المرء ولو كان مريضًا، إن قدر قائمًا؛ صلى قائمًا، وإن عجز؛ صلى قاعدًا، وإن عجز؛ صلى على جنبه. ولهذا لما اشتكى عمران بن حصين -رضي الله عنهما- إلى النبي ﷺ مرضه قال: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيًا فالمريض يصلي على حسب حاله، ولا يجوز له ترك الصلاة، بل يصلي على حسب طاقته، قائمًا إن قدر، فإن عجز؛ صلى قاعدًا، فإن عجز؛ صلى على جنبه، فإن عجز؛ صلى مستلقيًا؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والذي على جنبه، أو مستلقي يصلي بالذكر، وما يستطيع من الفعل، يكبر، ويقرأ، ويكبر وينوي الركوع يقول: سبحان ربي العظيم، يقول سمع الله ناويًا الرفع، وهو على جنبه، أو مستلقيًا، ثم يكبر ناويًا السجود، يقول: سبحان ربي الأعلى، وهكذا بالنية والكلام، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9994/حكم-من-ترك-الصلاة-لمرض-الم-به-عدة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42312.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":11914,"question":"هل يجوز لنا التيمم إذا كان البحر قريبًا منا، علمًا بأن الماء الذي معنا مخصص للشرب والأكل؟","title":"حكم التيمم مع قرب ماء البحر","answer":"الجواب:  نعم ليس لكم التيمم، ما دام البحر قريبًا؛ توضؤوا من البحر، يقول فيه النبي ﷺ: هو الطهور ماؤه، الحل ميتته، فالبحر ماؤه طهور والحمد لله، ولو كان مالحًا؛ يلزمكم الوضوء والغسل للجنابة من ماء البحر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10098/حكم-التيمم-مع-قرب-ماء-البحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42615.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":12550,"question":"يسأل أخونا سؤالًا آخر ويقول: تعرضت لحادث سيارة، وأصبحت الآن مقعدًا لا أتحرك إلا بواسطة العربية، ولا أتحكم في السبيلين، ولا أستطيع السيطرة عليهما، كيف تنصحونني في الوضوء، أو التيمم؟ جزاكم الله خيرًا.","title":"كيفية طهارة من لا يستطيع التحكم في الخارج من السبيلين","answer":"الجواب:  مثلك مثل صاحب السلس والمستحاضة، عليك أن تتوضأ لوقت كل صلاة، والحمد لله، إذا دخل وقت الصلاة؛ تستنجي، وتتوضأ وضوء الصلاة، وتصلي في الوقت حتى يجيء الوقت الآخر، ولو خرج شيء منك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هكذا كل وقت، تستنجي وتتوضأ وتصلي على حسب حالك، وتقرأ من المصحف، ولا حرج عليك في ذلك؛ لأنك معذور، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10757/كيفية-طهارة-من-لا-يستطيع-التحكم-في-الخارج-من-السبيلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41003.mp3","categories":["صلاة المريض","الطهارة لصحة الصلاة"]},{"id":12709,"question":"يقول أخونا في سؤال آخر: إذا أصيب الإنسان بالسلس لكبر، أو لمرض، هل يصلي، أم أن الصلاة تسقط عنه؟","title":"كيفية صلاة المصاب بسلس البول","answer":"الجواب:  الصلاة لا تسقط، ما دام العقل موجودًا؛ عليه أن يصلي، ولكن يتوضأ لكل صلاة، إذا أصابه السلس المستمر، وهو البول المستمر، الرطوبة؛ يتوضأ لكل صلاة، ويصلي كل صلاة في وقتها، مثل المستحاضة، الذي معها الدم الدائم، تتوضأ لكل صلاة، وتصلي، ولا تسقط عنها، ولا عن صاحب السلس الصلاة، ولهما الجمع إذا دعت الحاجة إذا شق عليهما الأمر، لكن الرجل ينبغي له ألا يجمع حتى يصلي مع الجماعة، أما المرأة فإذا جمعت لحاجة؛ فلا بأس؛ لأن الرسول ﷺ رخص لحمنة أن تجمع. فالحاصل: أن صاحب السلس يتوضأ لكل صلاة، ويصلي مع الجماعة، ويتحفظ بشيء من خرقة يربطها على ذكره؛ حتى لا ينتشر البول إلى الملابس، ويتوضأ لكل صلاة، والحمد لله، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا، إذا شعر بشيء أثناء الصلاة؟  الشيخ: ولو خرج شيء لا يضر. المقدم: لا يضر. الشيخ: لا يضر المرأة، ولا الرجل، المستحاضة وصاحب السلس، لا يضرهما ما خرج في الوقت، ولو في الصلاة. المقدم: ولو في الصلاة. الشيخ: نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10921/كيفية-صلاة-المصاب-بسلس-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45914.mp3","categories":["صلاة المريض"]},{"id":12852,"question":"المستمع فهد محمد سالم القحطاني من الرياض، بعث برسالة مطولة ملخص ما فيها: أنه رجل مرض بكسر في العمود الفقري، وهو مصاب باسترسال الحدث، ويسأل كيف تكون صلاته؟","title":"كيفية صلاة المصاب باسترسال الحدث","answer":"الجواب:  يقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] صل على حسب حالك، إذا كان الحدث مستمرًا، البول مستمرًا؛ صل على حسب حالك، إذا دخل الوقت؛ تستنجي ولو بالمناديل حتى تنظف بالمناديل ثلاث مرات فأكثر، ثم توضأ وضوء الصلاة، وتصلي على حسب حالك، ولو خرج الماء: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] مثل: المستحاضة التي تصلي على حسب حالها، ولو خرج الدم... ما دام الدم مستمرًا معها، تصلي في غير أوقات الحيض، وتدع الصلاة في وقت الحيض، وفي الأوقات الأخرى تصلي على حسب حالها، وتتوضأ لكل صلاة. وهكذا صاحب السلس الذي أصابه مرض، أو كسر في الفقر، في الظهر، أو ما أشبه ذلك، واستمر معه البول، أو الغائط يصلي على حسب حاله، لكن إذا دخل الوقت؛ يستنجي بالخرق والمناديل، أو بالماء، ثم يتوضأ وضوء الصلاة، ثم يصلي ولو خرج الحدث: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] نعم.","link":"https://binbaz.org.sa/fatwas/11067/كيفية-صلاة-المصاب-باسترسال-الحدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46418.mp3","categories":["صلاة المريض"]},{"id":12897,"question":"المستمع: علي عوض المبارك من السودان بعث يسأل ويقول: مرضت أمي مرضًا أقعدها في المنزل، ولم تستطع أن تصلي، وماتت وهي على ذلك الحال، فبم تنصحوننا تجاهها؟ جزاكم الله خيرًا.","title":"صفة صلاة المريض","answer":"الجواب:  ذهب عقلها، إن كان ذهب عقلها؛ فلا شيء، وإلا فالواجب أن تصلي ولو على جنب، وأنها تعلم وتصلي ولو على جنب، إذا لم تستطع الصلاة قائمة، ولا قاعدة يقول النبي ﷺ للمريض: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيا. هكذا يجب على المريض إن استطاع أن يصلي قائمًا؛ صلى قائمًا، ركع وسجد، وإن عجز؛ صلى قاعدًا، وأومأ بالركوع، وسجد في الأرض إن استطاع، وإلا أومأ بالركوع والسجود، وجعل السجود أخفض من الركوع، فإن عجز؛ صلى على جنب، والأفضل على جنبه الأيمن، يصلي باللفظ والنية، يكبر، فيقرأ الفاتحة، وما تيسر معها، ثم يكبر وينوي الركوع يقول: (سبحان ربي العظيم، سبحان ربي العظيم) ثم يقول: (سمع الله لمن حمده) وهو على جنبه، ناويًا الرفع من الركوع، ويقول: (ربنا ولك الحمد) إلى آخره. ثم يكبر ناويًا السجود، ويقول: (سبحان ربي الأعلى، سبحان ربي الأعلى) ويدعو ربه، ثم يكبر ناويًا الرفع من السجود، والجلسة بين السجدتين، يقول: (رب اغفر لي رب اغفر لي) ثم يكبر ناويًا السجدة الثانية، وهكذا.. حتى يكمل وهو على جنبه، أو مستلقيًا، وإذا كان مستلقيًا؛ يجعل رجليه إلى القبلة، يرفع رأسه قليلًا حتى يصلي إلى القبلة مثلما فعل الذي على جنب، يصلي بالنية والقول، ويرفع يديه إن كان يستطيع عند الإحرام، وعند الركوع، وعند الرفع منه، وعند القيام من التشهد الأول، إذا كان يستطيع يرفع يديه وهو على جنبه، أو مستلقيًا، أو قاعدًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11112/صفة-صلاة-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46712.mp3","categories":["صلاة المريض"]},{"id":13381,"question":"يوجد رجل كبير في السن، ومصاب بشلل نصفي، وهو يحرص على الصلاة في المسجد مع الجماعة، ويجلس على كرسي، ويضع أمامه بعض الأشياء المرتفعة عن سطح الأرض؛ ليتمكن وجهه من ملامستها أثناء السجود، فهل هذا صحيح؟ أم أنه يكتفي بأن يكون السجود الخفض من الركوع، مع عدم وجوب ملامسة الوجه؟","title":"العاجز هل يسجد على شيء مرتفع؟","answer":"الجواب: ما يحتاج يومي إيماء مثلما جاء في الحديث، حديث مرفوع وموقوف \"أن جابر رأى رجلًا يصلي على وسادة، فأمره بإلقاء الوسادة، وأن يومي بركوعه وسجوده\" ولا حاجة إلى وسادة يرفعها، بل يسجد في الهواء، ويخفض سجوده عن الركوع، ويكفي والحمد لله. لكن لو سجد على شيء رفعه، لو سجد عليه؛ لا يضر، لا حرج، لكن الأفضل أن يكون بالإيماء، إذا شق عليه السجود؛ يسجد في الهواء ... يخفضه عن الركوع، هذا هو السنة لمن عجز عن السجود في الأرض، ولا حاجة إلى وسادة، ولا كرسي، ولا شيء يسجد عليه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11671/العاجز-هل-يسجد-على-شيء-مرتفع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51508.mp3","categories":["صلاة المريض"]},{"id":13759,"question":"السائل يقول: هل يجوز للمريض أن يقصر الصلاة ويجمعها؟","title":"حكم قصر الصلاة وجمعها للمريض","answer":"الجواب: المريض ليس له قصر الصلاة، إنما هذا في حق المسافر خاصة، القصر يختص بالسفر، أما المريض لا يقصر، لكن له أن يجمع، يجمع الظهر والعصر، والمغرب والعشاء، جمعًا، يصلي الظهر أربعًا والعصر أربعًا جمعًا، يصلي المغرب ثلاثًا والعشاء أربعًا جمعًا، ليس له القصر، القصر من خصائص السفر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12130/حكم-قصر-الصلاة-وجمعها-للمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53523.mp3","categories":["صلاة المريض"]},{"id":14095,"question":"هل يجوز للمريض المقعد أن يصلي وهو جالس؟","title":"المريض المقعد هل له أن يصلي جالسًا؟","answer":"الجواب: المريض له الصلاة وهو جالس إذا شق عليه القيام، يصلي وهو جالس؛ لقوله ﷺ في الحديث الصحيح لـعمران بن حصين لما اشتكى، قال: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا، وهذا من تيسير الله، والحمد لله، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. فالمريض من الرجال أو النساء الذي يعجز أو يشق عليه القيام يصلي قاعدًا، فإن عجز عن القعود -لشدة المرض- صلى على جنبه الأيمن أفضل، أو الأيسر حسب التيسير والأيمن أفضل، فإن شق عليه ذلك؛ صلى مستلقيًا، وتكون رجلاه إلى القبلة، ويصلي مستقبلها بوجهه، أو وهو على ظهره.\nوهكذا المقعد الذي لا يستطيع القيام لشلل به يصلي قاعدًا ووجهه إلى القبلة، والحمد لله، ويسجد في الأرض، يركع في الهواء ويسجد في الأرض، يضع وجهه على الأرض في السجود، أما الركوع ففي الهواء، إلا إذا عجز عن السجود لمرض به يشق عليه السجود ويمنعه من السجود؛ فإنه يسجد في الهواء كالركوع، ويكون سجوده أخفض من الركوع، يركع في الهواء ويسجد في الهواء، لكن يكون السجود أخفض من الركوع إذا عجز عن السجود على الأرض؛ لأن الله  لا يكلف نفسًا إلا وسعها، ويقول : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12530/المريض-المقعد-هل-له-ان-يصلي-جالسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61006.mp3","categories":["صلاة المريض"]},{"id":14433,"question":"نعود أيضًا في هذه الحلقة إلى رسالة المستمع: سليمان بن علي نزال أبو هديب من الأردن، المفرق، عرضنا له سؤال في حلقة مضت وفي هذه الحلقة يقول: إن والدتي لا تقدر على القيام والركوع والسجود، وإنما تصلي جالسة، وتعمل تلك الأركان بالإشارة بيدها، ما صحة صلاتها؟","title":"كيف يصلي من عجز على القيام والركوع والسجود؟","answer":"الجواب: الله سبحانه يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] ويقول سبحانه: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286] فإذا كانت أمك لا تستطيع القيام صلت قاعدة، وإذا كانت لا تستطيع قاعدة صلت على جنبها، وإذا لم تستطع على جنبها صلت مستلقية ورجلاها إلى القبلة، هكذا جاء الحديث عن رسول الله -عليه الصلاة والسلام-؛ لما سأله بعض الصحابة -وكان مريضًا- عن الصلاة، قال: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هكذا السنة. وهكذا إذا عزم الركوع والسجود يفعل ما يستطيع، يخفض رأسه عند الركوع قليلًا، وعند السجود كذلك أخفض من الركوع إن استطاع، فإن لم يستطع بالكلِّية نوى الركوع ونوى السجود، ولا حاجة إلى الخفض: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16] إذا قرأ نوى الركوع، وقال: الله أكبر، سبحان ربي العظيم، سبحان ربي العظيم، وهو على حاله قاعدًا أو قائمًا، إذا كان لا يستطيع أن يحني رأسه، ولا ظهره شيئًا يأتي بذكر الركوع: سبحان ربي العظيم، سبحان ربي العظيم، وهو على حاله، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ثم يقول: سمع الله لمن حمده إذا كان منفرد، إن كان مأموم يقول: ربنا ولك الحمد، عندما يرفع إمامه وهو على حاله جالسًا أو قائمًا على حسب استطاعته. وهكذا في السجود، ينوي السجود وهو على جلسته إذا كان لا يستطيع السجود، ينوي السجود، ويخفض رأسه إن استطاع وظهره إن استطاع قدر ما يستطيع، فإن لم يستطع خفضًا كبر وهو على حاله كالركوع قال: الله أكبر، سبحان ربي الأعلى يكبر ناويًا السجود، ينوي بهذا السجود، ويقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ويدعو في سجوده بما تيسر من الدعوات، ثم يرفع قائلًا: الله أكبر، بنية الرفع، وهو على حاله: الله أكبر، ناويًا الرفع من السجود، ثم يقول: رب اغفر لي ، ناويًا الجلوس بين السجدتين، رب اغفر لي، رب اغفر لي، اللهم اغفر لي وارحمني، ثم يكبر ناويًا السجدة الثانية، وهو على حاله، سبحان ربي الأعلى، سبحان ربي الأعلى، إلى آخره، ثم يكبر ناويًا الرفع من السجود، وهكذا في صلاته كلها: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12940/كيف-يصلي-من-عجز-على-القيام-والركوع-والسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_632/nour_63202.mp3","categories":["صلاة المريض"]},{"id":14755,"question":"يقول أحدهما: كان لي والد مريض، وكان عاجزًا عن استعمال الماء وعن التيمم، ولم يصل فترة مرضه، وهي مدة خمسة عشر يومًا، ولما شفي من مرضه قضى الصلوات تلك، كل فرض مع ما يقابله من الفروض، فما هو رأيكم؟جزاكم الله خيرًا.","title":"حكم من ترك الصلاة أيام مرضه ثم قضاها","answer":"الجواب: أولاً هو غلطان، الواجب عليه أنه يفعل المستطاع، إن استطاع الماء توضأ، وإلا تيمم، وإن عجز يممه غيره: يممه أخوه أو زوجته أو غير ذلك، يضرب التراب بيديه، ويمسح به وجهه وكفيه بالنية عنه، يقول له: افعل، يأمره وهو ينوي، المريض ينوي والخادم أو وكيله يضرب التراب بيديه ويمسح بها وجهه وكفيه، إذا كان عاجزًا هو، أما أنه يصلي بدون وضوء وبدون تيمم هذا ما يجوز هذا.  وكونه يترك الصلاة لا يجوز أيضًا كل ذلك غلط منه، فإذا كان تركه لهذه العلة يظن أنه معذور بعجزه عن التيمم هذا عليه القضاء، ويقضي حالاً ما هو كل صلاة مع صلاة، لا، يقضيها جميعًا، ولو في وقت واحد، ولو في ضحوة واحدة يسردها. أما قول العامة: كل صلاة مع صلاة هذا لا أصل له، الذي عليه صلوات يسردها سردًا، في الضحى أو في الظهر الحمد لله، أو في الليل حسب طاقته يسردها، وليس لأحد أن يؤخر الصلاة لأجل ما عنده ماء ولا عنده تيمم، لا، بل يلزمه الوضوء، فإن لم يتيسر الماء تيمم، يحضرون له تراب من التراب الطيب ويضرب به يديه ويمسح وجهه وكفيه، فإن عجز لأنه ما يستطيع الحركة مريض، فالخادم الذي عنده الثقة، أو أخوه أو أمه أو أبوه ييممونه، يأمرهم بأن ييممونه وينوي هو بقلبه التيمم، ويضربون التراب ويمسحون وجهه وكفيه بالنية بالنيابة عنه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13244/حكم-من-ترك-الصلاة-ايام-مرضه-ثم-قضاها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49010.mp3","categories":["قضاء الفوائت","صلاة المريض"]},{"id":15356,"question":"يسأل أيضًا ويقول: هنالك رجل مصاب بمرض سلس البول، وهو شيخ كبير، وأكثر الأحيان، وفي أغلب الأوقات يكون فراشه غير نظيف، ولا يستطيع السيطرة على نفسه، وأيضًا لا يستطيع القيام من فراشه بسهولة، فهل تجوز له الصلاة على حالته هذه؟جزاكم الله خيرًا.","title":"كيفية صلاة الكبير المقعد الذي به سلس بول","answer":"الجواب: يقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فعليه أن يتوضأ لكل صلاة، ويتحفظ بخرقة، أو نحوها على فرجه، ويغسل ما أصاب بدنه وثيابه، أو يغسله له زوجته أو أولاده، ويجزئه ذلك، كل صلاة يتوضأ، ولو أن خرج منه بعد ذلك في الوقت، فيتوضأ للظهر، ويصلي ويقرأ القرآن من المصحف، لا بأس، حتى يجيء وقت العصر، فإذا جاء وقت العصر يعيد الوضوء مرة أخرى، إذا خرج منه شيء، وهكذا المغرب، وهكذا العشاء، وهكذا الفجر . والفراش يطهر له، يغير الرداء، طاهر، يصلي عليه كل صلاة، إذا كان الرداء أصابه بول يؤخر، لكن يجاب بداله، أو يغسل ما أصابه في كل وقت، وإذا نزل به شيء وهو يصلي لا يضره، مثل المستحاضة التي يجري بها الدم دائمًا فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لكن في الوقت، إذا خرج الوقت يعيد الوضوء ويعيده، ويغسل ما أصاب ثوبه، أو يبدله، وهكذا، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13859/كيفية-صلاة-الكبير-المقعد-الذي-به-سلس-بول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_498/49806.mp3","categories":["صلاة المريض"]},{"id":15405,"question":"هذا السائل من بريدة، رمز لاسمه بـ (ج. ر) يقول في هذا  سماحة الشيخ، هل للمريض أن يجمع في الصلاة، وإن كان كذلك؟ وهل الذي انكسرت رجله وجبست له، له أن يجمع في الصلاة؟أفتونا بذلك، جزاكم الله خيرًا.","title":"حكم الجمع بين الصلاتين للمريض","answer":"الجواب: نعم، المريض له أن يجمع بين الصلاتين، والمجبس مريض له أن يجمع، ولا حرج فيه، بين الظهر والعصر، والمغرب والعشاء، في وقت إحداهما، وإن لم يشق عليه صلى كل واحدة في وقتها، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13905/حكم-الجمع-بين-الصلاتين-للمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50003.mp3","categories":["صلاة المريض"]},{"id":15880,"question":"يسأل سماحتكم عن حكم من لم يتوضأ لبعض الصلوات خوفًا من البرد؟","title":"حكم ترك الوضوء خوفًا من البرد","answer":"الجواب: لا حرج، الحمد لله، إذا كان على وضوء، فالحمد لله يكفيكم الوضوء، أما إذا كان ما هو على وضوء يلزمه الوضوء، ولو كان برد، يسخن الماء، الحمد لله، يسخن الماء، ويتوضأ، نعم.\nالمقدم: جزاكم الله خيرًا، إذا كان بعيدًا عن وسائل التسخين سماحة الشيخ؟\nالشيخ: إذا كان عليه خطر ويضره الماء يتيمم، إذا كان برد ولا عنده شيء مما يسخن به الماء، ويضره الماء يتيمم والحمد لله؛ عذر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14472/حكم-ترك-الوضوء-خوفا-من-البرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74417.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":15921,"question":"مستمع رمز إلى اسمه بالحروف (ب. ج) يسأل ويقول: إنني أشكو من وجع في الظهر يمنعني من الركوع في الصلاة، ولكني بحمد الله أؤدي جميع أركان الصلاة، فما هو توجيهكم؟جزاكم الله خيرًا.","title":"ماذا يفعل من عجز عن الركوع لوجع بالظهر؟","answer":"الجواب: يقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فإذا كنت لا تستطيع الركوع تركع حسب طاقتك؛ وتحني رأسك وظهرك قليلًا حسب طاقتك، ولا بأس ولا حرج، فإن لم تستطع تكبر وتنوي الركوع مع الإمام، وفي النوافل، وأنت رافع فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وهكذا السجود، من عجز عنه سجد في الهواء خفض رأسه قليلًا حسب طاقته، وقال: سبحان ربي الأعلى، سبحان ربي الأعلى فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ثم يرفع رأسه.  المقصود: أنه يفعل ما يفعل المصلي، لكن من غير سجود، ولا ركوع حسب طاقته، فإذا عجز عن الركوع كبر للركوع وقال: سبحان ربي العظيم، سبحان ربي العظيم، ثم يقول: سمع الله لمن حمده إذا كان منفردًا، وإن كان مع الإمام إذا رفع الإمام يرفع هو ويقول: ربنا ولك الحمد.  وهكذا في السجود إذا عجز يكبر ساجدًا بنية السجود، ويخفض رأسه وظهره حسب طاقته، ويقول: سبحان ربي الأعلى، سبحان ربي الأعلى، ويدعو ربه، ثم يرفع ويكبر، الله أكبر إن كان وحده، وإن كان مع الإمام إذا رفع الإمام وكبر رفع وكبر فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والنبي ﷺ يقول -عليه الصلاة والسلام-: إذا أمرتكم بأمر فأتوا منه ما استطعتم هذا عام. هكذا الصيام الذي ما يستطيع الصيام؛ لكونه كبير السن، أو لمرض لا يرجى برؤه؛ يفطر ويطعم عن كل يوم مسكينًا، نصف صاع، كيلو ونصف عن كل يوم إذا كان كبير السن، أو عجوز كبيرة لا تستطيع الصيام، أو مريض مرضًا لا يرجى برؤه بتقرير الطبيب المختص؛ فهذا لا يلزمه الصوم، ولا عليه الصوم، يطعم عن كل يوم مسكينًا نصف صاع، مقداره كيلو ونصف تقريبًا، يعطيه بعض الفقراء، يجمعه كله ويعطيه بعض الفقراء، ولو فقيرًا وحدًا عن جميع الشهر. أما من يستطيع القضاء فهذا إذا مرض يفطر، ثم يقضي بعد ذلك، وهكذا المسافر إذا سافر وأفطر يقضي بعد ذلك؛ لأن الله سبحانه يقول: فَمَنْ كَانَ مِنْكُمْ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:184] يعني: مريض يستطيع القضاء، وأما إن كان لا يستطيع القضاء لكبر سنه أو عجوز لا تستطيع القضاء لكبر سنها، ما تستطيع الصيام؛ فإنها تفطر وتطعم عن كل يوم مسكينًا، تجمعها وتعطيها بعض الفقراء، والرجل كذلك يعطيه بعض الفقراء، وإن جعل الفقير مسكين يفطر معه كل يوم؛ لأنه لا يستطيع الصوم يفطر عنده كل يوم؛ حصل به المقصود يتعشى عنده كل يوم، فلا بأس لكن إذا أعطاه كفى، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14516/ماذا-يفعل-من-عجز-عن-الركوع-لوجع-بالظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_709/nour_70904.mp3","categories":["صلاة المريض"]},{"id":16205,"question":"من أحد الإخوة المستمعين هو خالد شكر محمود رسالة وضمنها بعض الأسئلة، يقول: إنني كنت أصلي وأصوم والحمد لله، وأقرأ القرآن، ولكن الآن تركت الصلاة منذ ثلاثة أعوام، والسبب أنني أصبت بإصابة شلل أطرافي السفلى، ونسبة العجز (100%)، ولا أستطيع أن أصلي، وليس هناك من يعينني، فبماذا توجهونني؟ جزاكم الله خيرًا، علمًا بأني أشرب في كل ساعتين نصف لتر من الماء حسب توجيه الطبيب، جزاكم الله خيرًا.","title":"الواجب على المريض الصلاة حسب طاقته","answer":"الجواب: عليك أن تصلي حسب طاقتك، يقول الله سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول سبحانه: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ويقول النبي ﷺ: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيًا. وعليك الوضوء بواسطة من يعينك على ذلك إذا تيسر ذلك، فإن عجزت عن الماء؛ فالتيمم، فإذا كانت يداك لا تستطيع بهما التيمم؛ فعليك أن تستعين بغيرك من زوجة، أو غيرها حتى توضئك بالماء إن تيسر، وإلا فالتيمم بالتراب، تمسح وجهك، وكفيك بالتراب، بالنية عنك، تأمرها بذلك، أنت تنوي وهي تفعل، أو خادم، أو ولد، أو أخ، تستعين بمن يتيسر من الناس حتى يقرب لك الماء إن استطعت الماء، فإن لم تستطع؛ فالتيمم. أما الخارج من السبيلين فيزال بالاستجمار، إن تيسر بالماء تزيله بالماء، فإن لم يتيسر؛ فبالاستجمار، بالحجارة، أو اللبن، أو بالمناديل، تزيل الأذى من الدبر، ومن الذكر بالمنديل، أو بالحجر، أو نحوهما ثلاث مرات، تكرر ثلاث مرات، أو أكثر حتى يزول الأثر؛ حتى يزول أثر الغائط، وأثر البول ثلاث مرات، أو أكثر.","link":"https://binbaz.org.sa/fatwas/14945/الواجب-على-المريض-الصلاة-حسب-طاقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80714.mp3","categories":["صلاة المريض"]},{"id":16244,"question":"من عدن المستمعة راقية إبراهيم رسالة، وضمنتها بعض الأسئلة، في أحدها تقول: أنا أعاني من الربو، ومن حساسية في الأنف مما يضطرني إلى تعاطي دواء للنوم في كل ليلة، وخاصة في أيام الشتاء، الأمر الذي يعيقني عن القيام لصلاة الصبح في وقتها، حيث أؤديها قضاءً مع صلاة الضحى، فهل يجوز ذلك؟ جزاكم الله خيرًا.","title":"حكم تأخير المريض الصلاة حتى يخرج وقتها","answer":"الجواب: لا يجوز ذلك، يجب عليك أن تصلي في الوقت على أي حالة تستطيعينها، ولا يجوز تأخير الصلاة إلى بعد طلوع الشمس، بل يجب أن تصلي في الوقت قائمة إن قدرت، فإن عجزت؛ صلي قاعدة، فإن عجزت؛ تصلي على جنب، فإن عجزت؛ فصلي مستلقية، هكذا يجب على المؤمن والمؤمنة عند وجود المرض، قد اشتكى عمران بن حصين -رضي الله عنهما- إلى النبي ﷺ مرضًا يجده، فقال له النبي ﷺ: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيًا والله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. فالواجب عليك أن تصلي على حسب الطاقة، في الوقت قبل طلوع الشمس، والأفضل التبكير بها بغلس عند اختلاط الصبح بظلمة الليل، على حسب القدرة فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إن استطعت أن تصلي قائمة؛ صلي قائمة، وإن عجزت؛ صلي قاعدة، وإن عجزت؛ فصلي على جنب، والجنب الأيمن أفضل إذا تيسر، فإن عجزت؛ فصلي مستلقية، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14943/حكم-تاخير-المريض-الصلاة-حتى-يخرج-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80712.mp3","categories":["صلاة المريض"]},{"id":16869,"question":"يسأل سؤالًا آخر، ويقول: امرأة كبيرة في السن، لا تضبط نفسها من حيث الطهارة، هل لها الجمع بين الصلوات؟","title":"جواز الجمع بين الصلاتين للمصاب بحدث دائم","answer":"الجواب: نعم، لا بأس أن تجمع، كالمريض؛ لأنها مريضة، فلا بأس أن تجمع بين الظهر والعصر في وقت إحداهما، وبين المغرب، والعشاء في وقت إحداهما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15627/جواز-الجمع-بين-الصلاتين-للمصاب-بحدث-داىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82420.mp3","categories":["صلاة المريض"]},{"id":16921,"question":"هذا سائل للبرنامج أبو عمرو الزعبي من الرمثا الأردن يقول: سماحة الشيخ، هل يجوز للمعذور من به سلس بول، أو رياح غليظة في بطنه، هل يجوز له الوضوء قبل دخول وقت الصلاة المفروضة؛ لكي يستطيع التبكير إلى المسجد، وإدراك تكبيرة الإحرام، والركعة الأولى، وكذلك لكي يستطيع أن يصلي السنة القبلية للفرض إذا كان المسجد بعيدًا؟ وجهونا في ضوء ذلك.","title":"بعض أحكام المصاب بسلس البول","answer":"الجواب: الواجب على من به الحدث الدائم ألا يتوضأ إلا بعد دخول الوقت، لقول النبي ﷺ للمستحاضة: توضئي لوقت كل صلاة فإذا كان به سلس البول، أو الريح فالوضوء يكون بعد دخول الوقت، بعد الزوال في الظهر، وبعد أن أن يصير ظل كل شيء مثله، بعد الزوال في العصر إذا أذن المؤذن للعصر، وبعد غروب الشمس للمغرب، بعد غروب الشفق في العشاء، بعد طلوع الفجر في الفجر، لا يتعجل، ويمديه -إن شاء الله- يصلي، ولو فاتته تكبيرة الإحرام، ولو فاته الركعة الأولى، لا يضر الحمد لله إذا كان المسجد بعيدًا، نعم. المقدم: يقول يا سماحة الشيخ حفظكم الله: من به سلس بول هل يجوز أن يكون إمامًا في الصلاة؟ الجواب: فيه خلاف بين العلماء، والأحوط له ألا يكون إمامًا؛ خروجًا من الخلاف، الأحوط أن يكون مأمومًا؛ خروجًا من خلاف من منع ذلك، نعم. المقدم: يقول: هل سلس البول الذي ينزل بعد الوضوء يؤثر على طهارة البدن، والثياب؟ الجواب: إذا كان في الوقت بعدما توضأ في الوقت، وهو معه السلس لا يؤثر، لكن متى خرج الوقت يطهر ثيابه، ينظف ثيابه، وما أصاب بدنه، أما في الوقت لو توضأ في الوقت، ثم خرج منه البول فإنه يصلي، ولو خرج، ولو أصاب ثيابه حتى ينتهي الوقت، مثلما في المستحاضة يخرج منها الدم، وتصلي، ولو خرج الدم منها، فإذا خرج الوقت؛ طهر ثيابه، وطهر بدنه، وأعاد الوضوء للوقت الآخر.","link":"https://binbaz.org.sa/fatwas/15680/بعض-احكام-المصاب-بسلس-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58607.mp3","categories":["صلاة المريض"]},{"id":17443,"question":"رسالة مؤثرة للغاية سماحة الشيخ، باعثتها إحدى الأخوات المستمعات تقول: أختكم في الله (ح. ع. ع) تقول عن نفسها: السلام عليكم ورحمة الله وبركاته، وبعد. أنا فتاة أصبت بحادث سيارة منذ أربع سنوات، تسبب لي هذا الحادث في شلل كامل، ما عدا الذراعين فهما سليمتان، والحمد لله، بعد إصابتي بهذا الحادث كنت أصلي بدون تيمم، أو وضوء، وسمعت من بعض الأخوات أنه يجب علي أن أتيمم، وأستعين في ذلك بخادمة، أو أي أحد يقوم بالضرب على التراب مرة واحدة، ثم أمسح على وجهي، وكفي، مع العلم أنه بعد التيمم لا أدري هل ظهر أثر التراب على مناطق التيمم، أو لا؟ ثم إنه عندما أشرع في الصلاة في بعض الأوقات لا أضبط نفسي بحكم الشلل، وقد ينتقض وضوئي، أرجو من سماحتكم توجيهي -جزاكم الله خيرًا- كما أرجو من سماحتكم الدعوات الطيبة؛ لعل الله أن ينفع بها.","title":"كيفية التيمم والصلاة لمن أصيب بالشلل","answer":"الجواب: وعليكم السلام ورحمة الله وبركاته، نسأل الله لك الشفاء والعافية، نسأل الله أن يمنحك الشفاء والعافية ويجمع لك بين الأجر والعافية، متى فعلت التيمم؛ كفى، ولو ما ظهرت آثار التراب عليه، متى ضربت التراب بيديك، أو من ينوب عنك، ضرب التراب بأمرك، ونيتك، ومسح على وجهك، وعلى كفيك؛ كفى ذلك، والحمد لله، وإن لم تعلمي ظهور آثار التراب، المهم أن يضرب التراب النائب عنك، أو أنت بنفسك، ثم تمسحين أنت، أو النائب وجهك والكفين بنية الطهارة، والحمد لله. وأما ما يتعلق بخروج الحدث في الصلاة فهذا فيه تفصيل: إن كان الحدث دائمًا معك في كل وقت؛ فلا يضرك خروجه في الوقت ما بعد الطهارة، أما إن كان لا، ليس بدائم، فإنه متى خرج تبطل الصلاة، وعليك أن تعيدي التيمم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16305/كيفية-التيمم-والصلاة-لمن-اصيب-بالشلل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83608.mp3","categories":["صلاة المريض","فروض الوضوء وصفته","التيمم"]},{"id":17740,"question":"السائلة (ع. ع. د) من جازان محافظة أبي عريش، تقول: سماحة الشيخ عبد العزيز بن باز حفظه الله السلام عليكم ورحمة الله وبركاته، وبعد:تذكر تقول: والدي شيخ كبير في السن، لا يستطيع الوقوف طويلًا في الصلاة، ولا يقوى على الركوع أو السجود؛ وذلك لأنه يشتكي من آلام شديدة في مفاصله؛ فلا يصلي إلا وهو جالس على مقعد، وإذا أراد الركوع أو السجود لا تصل أعضاؤه إلى الأرض، وجميع الصلوات يصليها في المنزل، علمًا بأننا إذا نصحناه أن يصلي في المسجد يجيبنا بقوله: إن الله يعلم بعجزي وضعفي يا أولادي، والسؤال يبقى يا سماحة الشيخ: هل يعذر الوالد في صلاته بالمنزل؟ وهل تصح الصلاة دون أن تصل الأعضاء إلى الأرض؟ جزاكم الله خيرًا.","title":"كيفية صلاة العاجز عن الركوع والسجود","answer":"الجواب: نعم إذا كان عاجزًا؛ تصح يصلي في الهواء؛ يركع في الهواء، ويسجد في الهواء، يصلي وهو قاعد، هو أعلم بنفسه، والله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، والنبي يقول ﷺ لـعمران بن حصين لما كان مريضًا: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا فالمؤمن يصلي حسب حاله، والله جل وعلا يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] والنبي يقول ﷺ إذا أمرتكم بأمر فأتوا منه ما استطعتم فإذا كان عاجزًا عن السجود في الأرض وعن الركوع؛ فإنه يفعل المستطاع: يركع المستطاع، ويسجد المستطاع، ويكون سجوده أخفض من ركوعه. نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16696/كيفية-صلاة-العاجز-عن-الركوع-والسجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59606.mp3","categories":["صلاة المريض"]},{"id":17835,"question":"السائل محمد أحمد من اليمن يقول: ما قول العلماء في سلس البول إذا حدث أثناء الصلاة هل يبطلها...الشيخ: أعد.المقدم: يقول: ما قول العلماء في مرض سلس البول إذا حدث أثناء الصلاة هل يبطلها؟ وهل يعيد الإنسان الوضوء كاملًا؟ أو يغسل موضع النجاسة فقط؟","title":"سلسل البول إذا حدث أثناء الصلاة هل يبطلها؟","answer":"الجواب: السلس مرض من الأمراض، الذي يصاب بالسلس في البول أو بالريح دائمًا هذا يلزمه أن يتوضأ لكل صلاة مثلما قال النبي ﷺ للمستحاضة التي معها الدم دائمًا: توضئي لوقت كل صلاة فإذا دخل الوقت توضأ وصلى على حسب حاله ولو خرج البول ما دام في الوقت يصلي، ويقرأ القرآن من المصحف، يصلي الفريضة والنافلة ما دام الوقت، فإذا خرج الوقت بطل وضوءه، وعليه أن يتوضأ وضوءًا آخر للصلاة الجديدة. وإذا كان بول أو غائط لا بد يستنجي عن البول والغائط، ثم يتوضأ في أطرافه، يغسل وجهه، يتمضمض ويستنشق، ويغسل وجهه وذراعيه مع المرفقين، ويمسح رأسه مع أذنيه، ويغسل قدميه مع الكعبين. أما إذا كان ريح أحدث بريح، أو مس فرجه، أو نوم فهذا يكفيه الوضوء .... ما يحتاج استنجاء بل يكفي غسل الأطراف الأربعة، يغسل وجهه وذراعيه، ويمسح رأسه ويغسل رجليه عن النوم، والريح، ومس الفرج، وأكل لحم الإبل ما يحتاج استنجاء، الاستنجاء من البول والغائط، إذا حصل بول أو غائط يستنجي يغسل فرجه، ويغسل دبره من الأذى، أو يستجمر بثلاثة أحجار فأكثر حتى ينقي المحل أو يجمع بينهما، يستجمر ويستعمل الماء كل هذا طيب.\nولا يلزمه هذا فيما يتعلق بالريح؛ الفساء، والضراط، هذا إذا خرج منه فساء أو ضراط ما فيه إلا الوضوء يعني: غسل الأطراف الأربعة، ما فيه استنجاء، هكذا إذا مس فرجه بيده، أو أكل لحم الإبل، أو نام نومًا يزول معه عقله نومًا مستغرق ينتقض وضوءه، وعليه الوضوء الذي هو غسل الأطراف الأربعة ما فيه استنجاء.\nأما صاحب السلس فإنه يتوضأ كل وقت إذا كان حدثه دائمًا، معه الريح دائم، معه البول دائم، هذا يتوضأ كل صلاة، كلما أذن يتوضأ، إن كان هناك بول أو غائط يستنجي، فإن كان ريح الريح معه دائم يتوضأ أطرافه فقط، يعني: يتمضمض ويستنشق، ويغسل وجهه، وذراعيه مع المرفقين، ثم يمسح رأسه مع أذنيه، ثم يغسل رجليه عن الريح ما فيها استنجاء، ولحم الإبل مثلًا، النوم المستغرق، مس الفرج. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16828/سلسل-البول-اذا-حدث-اثناء-الصلاة-هل-يبطلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77908.mp3","categories":["صلاة المريض","الطهارة لصحة الصلاة"]},{"id":18657,"question":"نعود في بداية هذه الحلقة إلى رسالة الأخت المستمعة أمينة حسن، من محافظة واسط، قضاء الصويرة، أختنا عرضنا بعضًا من أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول:طلب مني والدي أن أبعث إليكم بهذا  ذلكم أنه يجمع الصلوات، فمثلًا يصلي المغرب والعشاء في وقت واحد؛ فهو يصعب عليه أن يصليها في وقتها؛ لأنه ضخم الجسم، حيث يبلغ وزنه مائتين وعشرين كيلو، وهو يقول: عندما أقف على أقدامي فهي تؤلمني كثيرًا، فبماذا تنصحونه؟جزاكم الله خير الجزاء.","title":"حكم الجمع بين الصلاتين لعدم القدرة على القيام","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. يقول الله : فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول النبي ﷺ لما اشتكى إليه بعض المرضى: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب فإذا كان لا يستطيع القيام صلى قاعدًا، وصلى كل صلاة في وقتها، الظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، ومجرد كونه عاجز عن القيام لا يجعله يجمع بين الصلاتين. أما إذا كان معه مرض يشق عليه تفريق الصلاتين، والقيام لكل صلاة في وقتها؛ لمرضه وآلامه هذا شيء آخر، المريض له أن يجمع إذا كان مريضًا يتألم من قيام كل واحدة؛ لوجود أمراض معه من حمى أو غيرها من الأمراض التي يحصل بها مشقة عليه في إفراد كل صلاة في وقتها فلا بأس، وقد أذن النبي ﷺ للمستحاضة أن تجمع؛ لأن معها نوع مرض، فالمريض الذي معه آلام من حمى أو غيرها له أن يجمع بين الظهر والعصر، وبين المغرب والعشاء، أما الفجر فتصلى في وقتها، ولا تجمع إلى غيرها لا قبلها ولا بعدها، تصلى وحدها. وعليه مع ذلك أن يلاحظ قيامه في الصلاة، ولو خفيفًا يقرأ الفاتحة، وما تيسر معها، ولو قليلًا، وهو قائم؛ لأنه مأمور بالقيام، فإن عجز وشق عليه ذلك صلى قاعدًا، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17772/حكم-الجمع-بين-الصلاتين-لعدم-القدرة-على-القيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_872/nour_87201.mp3","categories":["صلاة المريض"]},{"id":18707,"question":"يقول هذا السائل الذي رمز لاسمه بـ (أ. ح. ع) يقول في سؤاله: أفيدكم سماحة الشيخ بأنني رجل كبير في السن أبلغ من العمر السبعين عامًا، وأنا أصلي الفروض الأربعة ما عدا صلاة الفجر، لا أستطيع أن أصليها حيث أنني لا أستطيع الوضوء، ونصحوني بعض الناس بعدم تشغيل المكيف؛ لأنه يؤثر على ركبتي، ولكنني لا أستغني عن هذا المكيف لشدة الحر، بعض الناس أفادوني قالوا لي: تيمم، والبعض قالوا: لا يجوز لك أن تتيمم حيث أن الماء موجود، فإذا حضر الماء بطل التيمم، فهل علي ذنب إذا تركت صلاة الفجر؟الشيخ: أعد أعد.المقدم: يقول هذا السائل: أفيدكم بأنني رجل كبير في السن أبلغ من العمر السبعين عامًا، وأنا أصلي الفروض الأربعة ما عدا صلاة الفجر لم أستطيع أن أصليها حيث أنني لا أستطيع الوضوء، ونصحوني بعض الناس بعدم تشغيل المكيف؛ لأنه يؤثر على ركبتي، ولكنني لا أستغني عن هذا المكيف لشدة الحر، وبعض الناس أفادوني وقالوا لي: تيمم، والبعض الآخر قالوا لي: التيمم غير مجزئ؛ لأن الماء موجود، فهل علي ذنب إذا تركت صلاة الفجر، حيث أني معذور، أو يجوز أن أصليها مع صلاة الظهر، ويجوز لي التيمم؟","title":"كيفية الطهارة للعاجز عن الوضوء","answer":"الجواب: الواجب عليك أن تصلي الفجر في وقتها، وإن كنت تستطيع تصليها في المسجد مع الجماعة وجب عليك أن تصلي مع الجماعة، فإن كان لا تستطيع لمرض في ركبتيك صلها في البيت، وعليك أن تتوضأ، ولو بماء مسخن إذا كان يشق عليك البارد يكون بماء مسخن حتى توضأ: تغسل وجهك، ويديك، وتمسح رأسك، وتغسل رجليك، فإذا كنت معك مرض يمنع من ذلك لا تستطيع الوضوء، وليس هناك زوجة تعينك على هذا الشيء أو ولد أو نحو ذلك؛ تيمم عند العجز؛ لأن الله يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا[النساء:43]. وهكذا العاجز الذي يجد، لكن لا يستطيع العمل لا يستطيع أن يتوضأ حكمه حكم من لم يجد، أما إذا كنت تستطيع تستعمل الماء في غرفتك، يحضر عندك الماء بإناء توضأ فيه؛ تغسل وجهك، ويديك، وتمسح رأسك، وتغسل رجليك بماء دافي؛ يلزمك، وليس لك التيمم. أما القبل والدبر فعليك أن تستعمل الاستجمار بالمناديل ويكفي، إذا مسحت الدبر والقبل بالمناديل ثلاث مرات فأكثر حتى تنقي المحل كفى، ويسمى الاستجمار، ثم توضأ وضوء الصلاة، تمضمض وتستنشق، وتغسل وجهك ويديك مع المرفقين، تمسح رأسك مع الأذنين، وتغسل رجليك بالماء المسخن، وإذا تيسر أن يساعدك أمك، أو أختك، أو زوجتك، أو ولدك؛ فالحمد لله، فإن عجزت عن هذا كله فالتيمم، والحمد لله، بالتراب في وجهك وكفيك، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17815/كيفية-الطهارة-للعاجز-عن-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78812.mp3","categories":["صلاة المريض","التيمم"]},{"id":18939,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يطلب أن توجهوه سماحتكم -جزاكم الله خيرًا- إلى مشروعية صلاة خاصة بالمريض، هل ورد في ذلك شيء؟","title":"بيان عدم مشروعية صلاة تخص المريض","answer":"الجواب: لا أعلم شيئًا يخص المريض، ولكن يتقي الله ما استطاع، والله -جل وعلا- يكتب له أجره، يقول ﷺ في الحديث الصحيح: إذا مرض العبد أو سافر؛ كتب الله له ما كان يعمل وهو صحيح مقيم والحمد لله، يعني: أعماله التي يعملها في الصحة تكتب له: من صلاة الضحى من صيام من غير ذلك، إذا منعه المرض تكتب له أجورها؛ لأنه حبسه عذر شرعي. يقول ﷺ لما كان في غزوة تبوك: إن في المدينة أقوامًا ما سرتم مسيرًا، ولا قطعتم واديًا، إلا وهم معكم وفي اللفظ الآخر: إلا شركوكم في الأجر قالوا: يارسول الله، وهم في المدينة؟ قال: وهم في المدينة، منعهم العذر (حبسهم المرض) فالمريض له أجوره التي له أجور أعماله التي كان يعملها في حال الصحة، وعليه أن يصلي الفريضة حسب طاقته، وإذا صلى النافلة حسب طاقته، فهذا خير وأفضل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18090/بيان-عدم-مشروعية-صلاة-تخص-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73624.mp3","categories":["صلاة المريض"]},{"id":18981,"question":"رسالة وصلت إلى البرنامج من السودان، وباعثتها إحدى الأخوات المستمعات، تقول (س. م. أ) أختنا لها ثلاثة أسئلة:في سؤالها الأول تقول: لي جدة كبيرة السن لا تستطيع الوضوء بحجة الرطوبة في رجليها، وتترك الصلاة بحجة عدم الوضوء، رغم أننا بينا لها التيمم وكيفيته؟أفيدونا جزاكم الله خيرًا.","title":"حكم ترك الصلاة للكبير في السن والمريض","answer":"الجواب: الواجب على المريض وعلى كبير السن مثل الواجب على غيرهما مع الاستطاعة، فعليهما الاستنجاء أو الاستجمار، عما يخرج من السبيلين، وعليهما الوضوء الشرعي، وعليهما الغسل إذا حصل جنابة، كل هذا معروف في الشرع المطهر، ومن عجز عن الوضوء لمرض يمنعه من ذلك، أو عجز يمنعه من ذلك، وتيسر من يوضئه وجب ذلك، وإن تعسر هذا وهذا تيمم بأن يقرب له التراب في إناء، أو في منديل أو بأشياء يضرب التراب بيديه، ويمسح بهما وجهه وكفيه، بنية الغسل من الجنابة، أو بنية الحدث الأصغر. أما ما يتعلق بالسبيلين فيكفي أن يمسحهما بالمناديل أو باللبن أو نحو ذلك، حتى ينقيهما، ولا يلزم الماء إن استنجى بالماء فالحمد لله، وإن لم يستنج بالماء كفاه أن يستجمر بالحجارة باللبن بالخرق حتى ينقي المحل، بمسحات ثلاث أو أكثر، لا بد من ثلاث مسحات، أو أكثر حتى ينقى المحل من الأذى، من الغائط والبول، وإذا فعل ذلك يتوضأ وضوء الصلاة بعد ذلك يتمضمض ويستنشق إلى آخره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18130/حكم-ترك-الصلاة-للكبير-في-السن-والمريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_925/nour_92504.mp3","categories":["صلاة المريض","حكم الصلاة وأهميتها"]},{"id":19364,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها سؤالين:في سؤاله الأول يقول: عندي والد كبير السن، ويجمع صلاة المغرب وصلاة العشاء؛ يصلي المغرب ثم العشاء وإذا نصحته قال: إنه لا يستطيع أن يبقى على الوضوء، ولا يستطيع أن يقوم في وقت العشاء، فما رأيكم؟ جزاكم الله خيرًا.","title":"حكم الجمع بين الصلاتين للكبير في السن","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كان والدك عاجزًا عن الصلاة في وقتها فلا بأس أن يجمع بين الصلاتين كالمريض، فالشيخ الكبير العاجز حكمه حكم المريض إذا احتاج إلى الجمع فلا بأس، أما إن كان يستطيع أن يقوم العشاء في وقتها والمغرب في وقتها من دون مشقة كبيرة فإنه لا يجمع، وإذا استطاع أن يصلي مع الناس في المساجد وجب عليه أن يصلي مع الناس في المساجد، أما إذا كان عاجزًا لا يستطيع الصلاة في المسجد ولا يستطيع الصلاة في الوقت الثاني -يعني: العشاء- فإنه يجمع ولا حرج في ذلك كما يجمع المريض والمسافر. المقدم: جزاكم الله خيرًا، هذا المسئول عنه سماحة الشيخ مريض وكبير في السن.\nالشيخ: لا بأس إن شاء الله، للأمرين للعلتين.\nالمقدم: للعلتين.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18562/حكم-الجمع-بين-الصلاتين-للكبير-في-السن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_900/nour_90001.mp3","categories":["صلاة المريض"]},{"id":19465,"question":"من أسئلتها يا سماحة الشيخ تقول: هل للمرأة أن تصلي وهي جالسة بدون صوت، وبدون أي حركة إذا كانت مريضة؟","title":"حكم صلاة المرأة وهي جالسة إذا كانت مريضة","answer":"الجواب: نعم مثل الرجل، النبي ﷺ قال: صل قائمًا فإن لم تستطع فقاعدًا إذا عجزت لمرض أو كبر سن صلت قاعدة والحمد لله كالرجل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18709/حكم-صلاة-المراة-وهي-جالسة-اذا-كانت-مريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93905.mp3","categories":["صلاة المريض"]},{"id":19723,"question":"بعد هذا رسالة بعث بها مستمع يقول: أخوكم أحمد الزين، أخونا أحمد يقول: إنني مريض في الفراش منذ فترة -أدام الله عليكم الصحة- هل لي أن أقضي الصلاة التي فاتتني من قبل؛ إذ أنني لا أعرف متى سيكون الشفاء، فهذا في علم الله؟","title":"حكم قضاء الصلاة لمن تركها بسبب المرض","answer":"الجواب: شفاكم الله وعافاكم، ونسأل الله لنا ولكم الشفاء والعافية.\nوالواجب عليك أن تصلي في مرضك، وأن تتوضأ الوضوء الشرعي؛ فإن عجزت تيممت بالتراب وتصلي كل صلاة في وقتها، وإن جمعت بين الظهر والعصر والمغرب والعشاء فلا بأس، هذا الواجب عليك. وإن كنت تركت شيئًا فعليك القضاء، إن كنت تركت شيئًا من الصلوات الخمس فعليك القضاء مع التوبة والاستغفار والندم، فهذه أمور عظيمة، والصلاة عمود الإسلام، والتعمد لتركها كفر؛ فالواجب عليك الحذر، وعدم التساهل، تصلي الصلاة لوقتها ولو جمعًا بين المغرب والعشاء والظهر والعصر، وإذا كنت عاجزًا عن الماء تيمم فإن استطعت الماء فافعل الماء. فالمقصود أن الواجب عليك أن تصلي كما شرع الله، ربك يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ.. [التغابن: 16]، فعليك أن تصلي حسب الطاقة، قائمًا إن قدرت، قاعدًا إن لم تستطع القيام، فإذا عجزت عن القعود صليت على جنبك، عجزت على الجنب تصلي مستلقيًا، وتقرأ وتنوي بقلبك أعمال الصلاة حسب الطاقة، ولا يجوز لك ترك الصلاة، فإذا كنت تركت شيئًا منها ظنًا منك أنه جائز فعليك القضاء، عليك القضاء. أما إن كنت تعمدت الترك تساهلاً منك فعليك التوبة ولا قضاء، عليك التوبة إلى الله والندم والإقلاع وعدم الرجوع إلى هذا الشيء ولا قضاء عليك؛ فإن قضيت فلا حرج؛ لأن بعض أهل العلم رأى عليك القضاء وأنك لا تكفر إلا بجحد الوجوب. ولكن الصواب أن من ترك الصلاة وإن لم يجحد الوجوب يكفر ولا قضاء عليه وعليه التوبة.","link":"https://binbaz.org.sa/fatwas/28601/حكم-قضاء-الصلاة-لمن-تركها-بسبب-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D9%82%D8%B6%D8%A7%D8%A1%20%D8%A7%D9%84%D8%B5%D9%84%D8%A7%D8%A9%20%D9%84%D9%85%D9%86%20%D8%AA%D8%B1%D9%83%D9%87%D8%A7%20%D8%A8%D8%B3%D8%A8%D8%A8%20%D8%A7%D9%84%D9%85%D8%B1%D8%B6.mp3","categories":["قضاء الفوائت","صلاة المريض"]}]
